-- GENERATED by data-pipeline (python -m wayfarer_pipeline cities). Do not edit by hand.

insert into public.cities (slug, name_en, name_pt, country_code, wikidata_id, center, bbox, timezone, is_active, summary_en, summary_pt, wikipedia_en, wikipedia_pt) values
  ('amsterdam', 'Amsterdam', 'Amesterdão', 'NL', 'Q727', extensions.st_setsrid(extensions.st_makepoint(4.883333, 52.366667), 4326)::extensions.geography, array[52.2781742,4.7287776,52.4310638,5.0791622]::double precision[], 'Europe/Amsterdam', true, 'Amsterdam is the capital and largest city of the Netherlands. As of 1 January 2026, it had a population of 941,873 within the city proper, 1,457,018 in the urban area and 2,480,394 in the metropolitan area. Located in the Dutch province of North Holland, Amsterdam is colloquially referred to as the "Venice of the North", for its large number of canals, now a UNESCO World Heritage Site.', 'Amesterdão (português europeu) ou Amsterdã (português brasileiro) ) é a capital e a cidade mais populosa do Reino dos Países Baixos. O seu estatuto de capital holandesa é garantido pela Constituição dos Países Baixos, embora não seja a sede do governo holandês, que fica em Haia. Amesterdão tinha em setembro de 2023, uma população de 930 205 habitantes na cidade propriamente dita, 1 470 595 habitantes em sua área urbana e 2 480 394 habitantes na área metropolitana. A cidade está localizada na província da Holanda do Norte, no oeste do país. É composta por grande parte da parte norte da Randstad, uma das maiores aglomerações urbanas da Europa, com uma população de aproximadamente 7 milhões de habitantes.', 'Amsterdam', 'Amesterdão'),
  ('andorra-la-vella', 'Andorra la Vella', 'Andorra-a-Velha', 'AD', 'Q1863', extensions.st_setsrid(extensions.st_makepoint(1.522222, 42.507222), 4326)::extensions.geography, array[42.4735326,1.4603314,42.5228745,1.5483185]::double precision[], 'Europe/Andorra', true, 'Andorra la Vella is the capital and largest city of Andorra. It is located high in the east Pyrenees, between France and Spain. It is also the name of the Andorran parish that surrounds the capital.', 'Andorra-a-Velha, é a capital e a mais populosa cidade do Principado de Andorra, pequeno país europeu situado entre a França e a Espanha. Com uma população de 19 383 habitantes, recebe mais de 10 milhões de turistas anualmente. Situada a 1 023 metros de altitude, é um importante destino turístico nos Pirenéus e a capital mais alta da Europa.', 'Andorra la Vella', 'Andorra-a-Velha'),
  ('antalya', 'Antalya', 'Antália', 'TR', 'Q6487', extensions.st_setsrid(extensions.st_makepoint(30.69556, 36.90812), 4326)::extensions.geography, array[36.7265728,30.5430242,37.0465728,30.8630242]::double precision[], 'Europe/Istanbul', true, 'Antalya is one of the largest cities in Turkey and the capital of Antalya Province, the fifth-most populous province. Recognized as the "capital of tourism" in Turkey and a pivotal part of the Turkish Riviera, Antalya sits on Anatolia''s southwest coast, flanked by the Taurus Mountains. The urban population of the city is around 1.5 million, with a provincial population of 2,722,103.', 'Antália, antiga Adália, é uma cidade do sul da Turquia, capital da área metropolitana e da província homónima, na região do Mediterrâneo. O conjunto dos distritos que a malha urbana da cidade ocupa, na totalidade ou parcialmente, tem 2 027 km² e em dezembro de 2021 tinha 1 462 129 habitantes. A altitude média da cidade é 30 m. Foi fundada cerca de 150 a.C.', 'Antalya', 'Antália'),
  ('antwerp', 'Antwerp', 'Antuérpia', 'BE', 'Q12892', extensions.st_setsrid(extensions.st_makepoint(4.399722, 51.221111), 4326)::extensions.geography, array[51.1432868,4.2175769,51.3776356,4.5090543]::double precision[], 'Europe/Brussels', true, 'Antwerp is a city and a municipality in the Flemish Region of Belgium. It is the capital and largest city of Antwerp Province, and the third-largest municipality in Belgium by area at 208.22 km2 (80.39 sq mi). With a population of 565,039, it is the most populous municipality in Belgium, and with a metropolitan population of over 1.2 million people, the country''s second-largest metropolitan area after Brussels.', 'Antuérpia é a maior cidade da região da Flandres na Bélgica, com uma população total de 1.061.089. É conhecida como centro mundial de lapidação de diamantes e por seu porto, um dos maiores do mundo, localizado nas margens do rio Escalda. Sua área total é de 204,51 km², dando uma densidade populacional de 5.188 habitantes por km². A área metropolitana, incluindo a zona exterior suburbana, cobre uma área de 1 449 km² e uma população acima dos 1,2 milhão de habitantes em 2024. Os habitantes de Antuérpia são localmente apelidado Sinjoren, após o título honorífico espanhol señor. Refere-se aos nobres líderes espanhóis que governaram a cidade durante o século XVII.', 'Antwerp', 'Antuérpia'),
  ('athens', 'Athens', 'Atenas', 'GR', 'Q1524', extensions.st_setsrid(extensions.st_makepoint(23.728056, 37.984167), 4326)::extensions.geography, array[37.8155648,23.5748324,38.1355648,23.8948324]::double precision[], 'Europe/Athens', true, 'Athens is the capital and largest city of Greece. A significant coastal urban area in the Mediterranean, Athens is also the capital of the Attica region and is the southernmost capital on the European mainland. With its urban area''s population numbering over 3.6 million, it is the eighth-largest urban area in the European Union (EU). The Municipality of Athens, which constitutes a small administrative unit of the entire urban area, had a population of 643,452 in 2021, within its official limits, and a land area of 38.96 square kilometres. Athens joined the UNESCO Global Network of Learning Cities in 2016.', 'Atenas ; em grego antigo: Ἀθῆναι, transl.: Athēnai) é a capital e a maior cidade da Grécia. A cidade domina a região da Ática e é uma das cidades mais antigas do mundo, sendo que seu território está continuamente habitado há 3 400 anos. A Atenas Clássica, do período da Grécia Antiga, foi uma poderosa pólis (cidade-Estado) que surgiu em conjunto com o desenvolvimento do porto de Pireu. Um centro artístico, estudantil e filosófico desde a Antiguidade, a cidade sediou a Academia de Platão e o Liceu de Aristóteles, além de ser amplamente considerada como o berço da civilização ocidental e da democracia, em grande parte devido ao impacto de suas realizações culturais e políticas durante os séculos IV e V a.C. no resto do continente europeu. Atualmente, é uma metrópole cosmopolita e o centro econômico, financeiro, industrial, político e cultural da Grécia. Em 2012, Atenas foi classificada como a 39ª cidade mais rica do mundo por paridade do poder de compra (PPC) e a 77ª mais cara em um estudo do UBS AG.', 'Athens', 'Atenas'),
  ('barcelona', 'Barcelona', 'Barcelona', 'ES', 'Q1492', extensions.st_setsrid(extensions.st_makepoint(2.176944, 41.3825), 4326)::extensions.geography, array[41.3170354,2.0524977,41.4679135,2.2283555]::double precision[], 'Europe/Madrid', true, 'Barcelona is a city on the northeastern coast of Spain. It is the capital and largest city of the autonomous community of Catalonia, as well as the second-most populous municipality of Spain after Madrid. With a population of 1.7 million within city limits, its urban area extends to numerous neighbouring municipalities within the province of Barcelona and is home to around 5.7 million people, making it the fifth most populous urban area of the European Union after Paris, the Ruhr area, Madrid, and Milan. It is one of the largest metropolises on the Mediterranean Sea, located on the coast between the mouths of the rivers Llobregat and Besòs, and bounded to the west by the Serra de Collserola mountain range.', 'Barcelona é a capital da comunidade autônoma da Catalunha, Espanha, bem como o segundo município mais populoso do país, com uma população de 1,6 milhão dentro dos limites da cidade. A sua área urbana se estende para além dos limites administrativos da cidade com uma população de cerca de 4,7 milhões de pessoas, sendo a sexta área urbana mais populosa da União Europeia, depois de Paris, Londres, Madri, Vale do Ruhr e Milão. É a maior metrópole do Mar Mediterrâneo, localizada na costa entre as foz dos rios Llobregat e Besòs, e limitada ao oeste pela Serra de Collserola, cujo pico mais alto é de 512 metros de altura.', 'Barcelona', 'Barcelona'),
  ('bath', 'Bath', 'Bath', 'GB', 'Q22889', extensions.st_setsrid(extensions.st_makepoint(-2.359722, 51.381389), 4326)::extensions.geography, array[51.3505346,-2.4141955,51.4112023,-2.3157642]::double precision[], 'Europe/London', true, 'Bath is a city in Somerset, England, known for and named after its Roman-built baths. The city became a UNESCO World Heritage Site in 1987, and was later listed as one of the "Great Spa Towns of Europe". Bath is in the valley of the River Avon, 97 miles west of London and 11 miles southeast of Bristol, and is the largest city and urban settlement in Somerset.', 'Bath é uma cidade do sudoeste de Inglaterra, localizada no Condado de Somerset. É muito conhecida pelas suas termas que provêm de três nascentes.', 'Bath, Somerset', 'Bath'),
  ('belfast', 'Belfast', 'Belfast', 'GB', 'Q10686', extensions.st_setsrid(extensions.st_makepoint(-5.93, 54.596667), 4326)::extensions.geography, array[54.5305618,-6.0601801,54.6649674,-5.8073559]::double precision[], 'Europe/London', true, 'Belfast is the capital, largest city and main port of Northern Ireland. It stands on the banks of the river Lagan, and is connected to the open sea through Belfast Lough and the North Channel. The city is the most populous in Northern Ireland and the second-largest, after Dublin, on the island of Ireland, with a recorded population in 2021 of 345,418 and of 704,406 for the greater metropolitan area.', 'Belfast, Belfástia ou Belfaste é a capital da Irlanda do Norte e da província do Ulster, sendo a segunda maior cidade na ilha da Irlanda. Enquanto a população dentro dos limites da cidade é de cerca de 352 390 pessoas, cerca de 652 000 pessoas vivem na área da Grande Belfast. Situa-se próxima à foz do rio Lagan. É flanqueada por trechos de montanha nos dois lados.', 'Belfast', 'Belfast'),
  ('belgrade', 'Belgrade', 'Belgrado', 'RS', 'Q3711', extensions.st_setsrid(extensions.st_makepoint(20.456944, 44.817778), 4326)::extensions.geography, array[44.6880459,20.2213764,44.9426876,20.6232109]::double precision[], 'Europe/Belgrade', true, 'Belgrade is the capital and largest city of Serbia. It is located at the confluence of the Sava and Danube rivers and at the crossroads of the Pannonian Plain and the Balkan Peninsula. According to the 2022 census, the population of Belgrade city proper stands at 1,197,114, its contiguous urban area has 1,298,661 inhabitants, while the population of the city''s administrative area totals 1,682,720 people. It is one of the major cities of Southeast Europe and the third-most populous city on the river Danube.', 'Belgrado ) é a capital e maior cidade da Sérvia, e está localizada entre dois cursos de água internacionais, na confluência dos rios Danúbio e Sava, no norte da Sérvia, onde a planície da Panônia se limita com a região da península balcânica. Com uma população de 1 710 000 habitantes (2007), Belgrado é a maior cidade no território da ex-Iugoslávia, a segunda maior cidade sobre o rio Danúbio, bem como a quarta maior do Sudeste da Europa, após Istambul, Atenas e Bucareste.', 'Belgrade', 'Belgrado'),
  ('bergen', 'Bergen', 'Bergen', 'NO', 'Q26793', extensions.st_setsrid(extensions.st_makepoint(5.323333, 60.3925), 4326)::extensions.geography, array[60.1760905,5.1445788,60.5360925,5.6867918]::double precision[], 'Europe/Oslo', true, 'Bergen is a city and municipality in the Vestland county on the west coast of Norway. Bergen is the second-largest city in Norway after the capital, Oslo.', 'Bergen ou Berga é a segunda maior cidade da Noruega, com uma população de 286 930 habitantes em 2022. A cidade está cercada por sete montanhas, o que lhe confere uma bela paisagem, mas também altos índices de precipitação, já que as montanhas servem como barreira natural para as nuvens do mar do Norte.', 'Bergen', 'Bergen'),
  ('berlin', 'Berlin', 'Berlim', 'DE', 'Q64', extensions.st_setsrid(extensions.st_makepoint(13.383333, 52.516667), 4326)::extensions.geography, array[52.3382448,13.088345,52.6755087,13.7611609]::double precision[], 'Europe/Berlin', true, 'Berlin is the capital and largest city of Germany. With 3.7 million inhabitants, it has the highest population within its city limits of any city in the European Union (EU). The metropolis is also one of the states of Germany, being the third-smallest state in the country by area. Berlin is surrounded by the state of Brandenburg, bordering Brandenburg''s capital Potsdam to the southwest. The urban area of Berlin has a population of 4.5 million, making it the second most populous in Germany after the Ruhr. The Berlin-Brandenburg capital region has around 6.2 million inhabitants and is Germany''s second-largest metropolitan region after the Rhine-Ruhr region, as well as the fifth-biggest metropolitan region by GDP in the EU. Berlin is a global city of culture, politics, media and science.', 'Berlim é a capital e um dos dezesseis estados da Alemanha. Com uma população de 3,5 milhões dentro de limites da cidade, é a maior cidade do país, e a sétima área urbana mais povoada da União Europeia. Situada no nordeste da Alemanha, é o centro da área metropolitana de Berlim-Brandemburgo, que inclui 5 milhões de pessoas de mais de 190 nações. Localizada na grande planície europeia, Berlim é influenciada por um clima temperado sazonal. Cerca de um terço da área da cidade é composta por florestas, parques, jardins, rios e lagos.', 'Berlin', 'Berlim'),
  ('bern', 'Bern', 'Berna', 'CH', 'Q70', extensions.st_setsrid(extensions.st_makepoint(7.44743, 46.94798), 4326)::extensions.geography, array[46.9190335,7.2943138,46.9901535,7.4955575]::double precision[], 'Europe/Zurich', true, 'Bern, or Berne, is the de facto capital of Switzerland, referred to as the "federal city". With a population of about 146,000, Bern is the fifth-most populous city in Switzerland, behind Zurich, Geneva, Basel and Lausanne. The Bern agglomeration, which includes 36 municipalities, had a population of 406,900 in 2014. The metropolitan area had a population of 660,000 in 2000.', 'Berna ; em francês: Berne [bɛʁn]; em italiano: Berna [ˈbɛrna]; em romanche: Berna [ˈbɛrnə]) é a capital de facto da Suíça. Berna é uma cidade predominantemente germanófona, capital do cantão homônimo e também uma comuna.', 'Bern', 'Berna'),
  ('bilbao', 'Bilbao', 'Bilbau', 'ES', 'Q8692', extensions.st_setsrid(extensions.st_makepoint(-2.935, 43.263056), 4326)::extensions.geography, array[43.2137176,-2.9859808,43.2901315,-2.8802639]::double precision[], 'Europe/Madrid', true, 'Bilbao is a city in northern Spain, the largest city in the province of Biscay and in the autonomous community of the Basque Country. With a population of 347,342 as of 2024, it is the 11th most populous city in Spain, and the most populous in northern Spain. The Bilbao metropolitan area has 1,037,847 inhabitants, making it the most populous metropolitan area in northern Spain. The comarca of Greater Bilbao is the fifth-largest urban area in Spain. Bilbao is also the main urban area in what is defined as the Greater Basque region.', 'Bilbau é um município e cidade da comunidade autónoma do País Basco, Espanha, capital da província e território histórico da Biscaia. O município tem 41,3 km² de área e em 2021 tinha 346 405 habitantes. A conurbação onde se insere, a área metropolitana de Bilbau, que se estende ao longo da ria de Bilbau e do rio Nervión, tinha 910 298 habitantes em 2009, ou seja, pouco menos que 80% de toda a população da Biscaia e quase metade do País Basco espanhol.', 'Bilbao', 'Bilbau'),
  ('bologna', 'Bologna', 'Bolonha', 'IT', 'Q1891', extensions.st_setsrid(extensions.st_makepoint(11.342778, 44.493889), 4326)::extensions.geography, array[44.4210532,11.2296206,44.556094,11.4334471]::double precision[], 'Europe/Rome', true, 'Bologna is the capital and largest city of the Emilia-Romagna region in northern Italy. It is the seventh most populous city in Italy, with 391,473 inhabitants from 150 different nationalities. Its metropolitan province is home to more than 1 million people as of 2026. Bologna is most famous for being the home to the oldest university in continuous operation, the University of Bologna, established in AD 1088.', 'Bolonha é uma comuna italiana, capital e a maior cidade da região da Emília-Romanha, província de Bolonha, mais especificamente, entre os rios Reno e o Savena. Bolonha é uma cidade universitária com cerca de 400 000 habitantes, sendo a sétima maior cidade em termos de população na Itália e é o coração de uma área metropolitana de cerca de 1 000 000 habitantes. Localiza-se no centro norte do país. Estende-se por uma área de 140 km², tendo uma densidade populacional de 2 643 hab/km².', 'Bologna', 'Bolonha'),
  ('bordeaux', 'Bordeaux', 'Bordéus', 'FR', 'Q1479', extensions.st_setsrid(extensions.st_makepoint(-0.579444, 44.837778), 4326)::extensions.geography, array[44.8107802,-0.6386987,44.9161806,-0.5336838]::double precision[], 'Europe/Paris', true, 'Bordeaux is a city on the river Garonne in the Gironde department, southwestern France. A port city, it is the capital of the Nouvelle-Aquitaine region, as well as the prefecture of the Gironde department. Its inhabitants are called "Bordelais" (masculine) or "Bordelaises" (feminine). The term "Bordelais" may also refer to the city and its surrounding region.', 'Bordéus ou Bordeaux é a capital e a maior cidade do departamento da Gironda e da região Nova Aquitânia, no sudoeste da França. Designou-se Burdígala na Antiguidade.', 'Bordeaux', 'Bordéus'),
  ('brasov', 'Brașov', 'Brașov', 'RO', 'Q82174', extensions.st_setsrid(extensions.st_makepoint(25.610556, 45.652222), 4326)::extensions.geography, array[45.499647,25.5035642,45.752328,25.6889236]::double precision[], 'Europe/Bucharest', true, 'Brașov is a city in Transylvania, Romania and the county seat of Brașov County.', 'Brașov é um município e cidade da região histórica da Transilvânia, Roménia. É a capital do distrito (județ) homónimo e a 6.ª maior cidade do país em população. Tem 267,3 km² de área e em 2021 tinha 290 743 habitantes(densidade: 1 087,7 hab./km²). A área metropolitana de Brașov tem 1 368,5 km² de área e em 2021 tinha 371 802 habitantes.', 'Brașov', 'Brașov'),
  ('bratislava', 'Bratislava', 'Bratislava', 'SK', 'Q1780', extensions.st_setsrid(extensions.st_makepoint(17.10674, 48.14816), 4326)::extensions.geography, array[48.0066643,16.946044,48.2650685,17.284531]::double precision[], 'Europe/Bratislava', true, 'Bratislava is the capital and largest city of Slovakia and the fourth largest of all cities on the river Danube. Officially, the population of the city proper is about 479,000, with the wider Bratislava Region exceeding 732,000 inhabitants. The metropolitan area has a population of approximately 1.3 million.', 'Bratislava ; antigamente em eslovaco: Prešporok; em alemão:  Pressburg ou Preßburg; em húngaro:  Pozsony; em latim: Posonium) é a capital e principal cidade da Eslováquia, situada no sudoeste do país, junto da fronteira com a Áustria e da fronteira com a Hungria, tornando-se, assim, na única capital europeia situada na fronteira do seu país com outros dois. A cidade é também cortada pelo rio Danúbio em seu curso. Com 475 mil habitantes (2021), é a maior cidade do país. Os Cárpatos, uma das notórias cordilheiras europeias, começam no território da cidade. Sede da presidência, do parlamento e do governo eslovacos, Bratislava conta ainda com universidades, museus, teatros e toda infraestrutura comum às grandes cidades no que tange à vida política, cultural e social da Europa.', 'Bratislava', 'Bratislava'),
  ('bruges', 'Bruges', 'Bruges', 'BE', 'Q12994', extensions.st_setsrid(extensions.st_makepoint(3.224167, 51.208889), 4326)::extensions.geography, array[51.1582193,3.1341748,51.363347,3.3098982]::double precision[], 'Europe/Brussels', true, 'Bruges is the capital and largest city of the province of West Flanders, in the Flemish Region of Belgium. It is located in the northwest of the country, and is the sixth most populous city in Belgium. The predominant language is Dutch.', 'Bruges ; em francês: Bruges [bʁyːʒ]  ; em alemão: Brügge [ˈbrʏɡə]) é uma cidade belga, capital da província de Flandres Ocidental, na região da Flandres. Tem cerca de 117 mil habitantes (2013). Foi a capital europeia da cultura em 2002, juntamente com a cidade espanhola de Salamanca.', 'Bruges', 'Bruges'),
  ('brussels', 'Brussels', 'Bruxelas', 'BE', 'Q239', extensions.st_setsrid(extensions.st_makepoint(4.351667, 50.846667), 4326)::extensions.geography, array[50.7963454,4.3137681,50.9139045,4.4370662]::double precision[], 'Europe/Brussels', true, 'The City of Brussels is the largest municipality and historical centre of the Brussels-Capital Region, as well as the capital of Belgium. It is additionally the capital of the French Community of Belgium, the Flemish Community, and the Flemish Region. The City of Brussels is also the administrative centre of the European Union, as it hosts a number of principal EU institutions in its European Quarter.', 'A Cidade de Bruxelas é a maior comuna da Região da Capital Bruxelas que, por sua vez, é a capital da Bélgica.', 'City of Brussels', 'Cidade de Bruxelas'),
  ('bucharest', 'Bucharest', 'Bucareste', 'RO', 'Q19660', extensions.st_setsrid(extensions.st_makepoint(26.097778, 44.413361), 4326)::extensions.geography, array[44.3342466,25.9666745,44.5413964,26.2255768]::double precision[], 'Europe/Bucharest', true, 'Bucharest is the capital and largest city of Romania. The metropolis stands on the River Dâmbovița in south-eastern Romania. Its population is officially estimated at 1.71 million residents within a greater metropolitan area of 2.33 million residents, which makes Bucharest the 9th most-populous city by population within city limits in the European Union. The city has an area of 239 km2 (92 sq mi), while the metropolitan area covers 1,803 km2 (696 sq mi). The city proper is administratively known as the "Municipality of Bucharest", and has the same administrative level as that of a national county, being further subdivided into six sectors, each governed by a local mayor. Bucharest is a major cultural, political and economic hub, the country''s seat of government, and the capital of the Muntenia region. It is an enclave completely surrounded by Ilfov County.', 'Bucareste ) é a capital e maior cidade da Roménia. Além de capital oficial, é também a capital cultural, industrial e financeira do país. Está localizada na parte sudeste da Roménia, na região histórica da Munténia, nas margens do rio Dâmbovița, cerca de 60 km a norte do rio Danúbio e da fronteira com a Bulgária.', 'Bucharest', 'Bucareste'),
  ('budapest', 'Budapest', 'Budapeste', 'HU', 'Q1781', extensions.st_setsrid(extensions.st_makepoint(19.040833, 47.498333), 4326)::extensions.geography, array[47.3496899,18.9251057,47.6131468,19.3349258]::double precision[], 'Europe/Budapest', true, 'Budapest is the capital and most populous city of Hungary. It is Hungary''s primate city with 1.7 million inhabitants and its greater metro area has a population of about 3.3 million, representing one-third of the country''s population and producing more than 40% of the country''s economic output. Budapest is the political, economic, and cultural center of the country, among the ten largest cities in the European Union and the second largest urban area in Central and Eastern Europe. Budapest stands on the River Danube and is strategically located at the center of the Pannonian Basin, lying on ancient trade routes linking the hills of Transdanubia with the Great Plain.', 'Budapeste é a capital, cidade mais populosa e principal centro financeiro, corporativo, mercantil e cultural da Hungria. É a nona maior cidade da União Europeia e recebeu a classificação de cidade global alpha, por parte do Globalization and World Cities Study Group & Network (GaWC). Localiza-se nas margens do rio Danúbio e possui 1 740 041 habitantes, de acordo com dados de 2012 do Centro de Estatísticas Húngaro. Sua região metropolitana, também chamada de Grande Budapeste, possui 3 271 110 habitantes. Budapeste foi fundada em 17 de novembro de 1873 com a fusão das cidades de Buda e Ôbuda, na margem direita do Danúbio, com Peste, na margem esquerda. Seus habitantes chamam-se budapestinos.', 'Budapest', 'Budapeste'),
  ('cardiff', 'Cardiff', 'Cardiff', 'GB', 'Q10690', extensions.st_setsrid(extensions.st_makepoint(-3.179167, 51.481667), 4326)::extensions.geography, array[51.3216546,-3.3391934,51.6416546,-3.0191934]::double precision[], 'Europe/London', true, 'Cardiff is the capital and largest city of Wales. Cardiff had a population of 383,919 in 2024 and forms a principal area officially known as the City and County of Cardiff. The city is the eleventh largest in the United Kingdom. Located in the southeast of Wales, the city sits within the Cardiff Capital Region, which consists of 1.5 million people, accounting for roughly half the nation''s total population. Cardiff is the county town of the historic county of Glamorgan and from 1974 to 1996 of South Glamorgan. It belongs to the Eurocities network of the largest European cities. A small town until the early 19th century, its prominence as a port for coal when mining began in the region helped its expansion. In 1905, it was ranked as a city and in 1955 proclaimed capital of Wales. The Cardiff urban area covers a larger area outside the county boundary, including the towns of Dinas Powys and Penarth.', 'Cardiff ou, nas suas formas portuguesas, Cardife ou, mais raramente, Cardívio é a capital e uma subdivisão administrativa autônoma, Principal Area, do País de Gales.', 'Cardiff', 'Cardiff'),
  ('coimbra', 'Coimbra', 'Coimbra', 'PT', 'Q45412', extensions.st_setsrid(extensions.st_makepoint(-8.428889, 40.211111), 4326)::extensions.geography, array[40.0989228,-8.5916759,40.3520146,-8.3129036]::double precision[], 'Europe/Lisbon', true, 'Coimbra, officially the City of Coimbra, is a city and a municipality in Portugal. The population of the municipality at the 2021 census was 140,796, in an area of around 319.40 square kilometres (123.3 sq mi).
It is the fourth-largest metropolitan area in Portugal after Lisbon, Porto, and Braga, and it is the largest city of the district of Coimbra and the Central Region, and about 460,000 people live in its intermunicipal community.', 'Coimbra é a cidade capital do Distrito de Coimbra, contando com 156 000 habitantes (2021) no seu perímetro urbano. Coimbra está inserida na sub-região Região de Coimbra e na Região do Centro.', 'Coimbra', 'Coimbra'),
  ('cologne', 'Cologne', 'Colónia', 'DE', 'Q365', extensions.st_setsrid(extensions.st_makepoint(6.957778, 50.942222), 4326)::extensions.geography, array[50.8304399,6.7725303,51.0849743,7.162028]::double precision[], 'Europe/Berlin', true, 'Cologne is the fourth-most populous city of Germany and the largest city of the German state of North Rhine-Westphalia with over 1.0 million inhabitants in the city proper and over 3.1 million people in the Cologne Bonn urban region. Cologne is also part of the Rhine-Ruhr metropolitan region, the second biggest metropolitan region by GDP in the European Union. Centred on the left bank of the Rhine, Cologne is located on the River Rhine, about 35 kilometres (22 mi) southeast of the North Rhine-Westphalia state capital Düsseldorf and 22 kilometres (14 mi) northwest of Bonn, the former capital of West Germany.', 'Colônia  (português brasileiro) ou Colónia (português europeu) e raramente Colonha é a maior cidade do estado federal alemão da Renânia do Norte-Vestefália e a quarta cidade mais populosa da Alemanha. Está localizada na região metropolitana do Reno-Ruhr, que é a maior metrópole alemã e umas das principais da Europa. Colônia fica a cerca de 45 quilômetros a sudoeste da capital de Dusseldorf e a 25 quilômetros a noroeste de Bona.', 'Cologne', 'Colônia (Alemanha)'),
  ('copenhagen', 'Copenhagen', 'Copenhaga', 'DK', 'Q1748', extensions.st_setsrid(extensions.st_makepoint(12.568889, 55.676111), 4326)::extensions.geography, array[55.5267243,12.4100724,55.8467243,12.7300724]::double precision[], 'Europe/Copenhagen', true, 'Copenhagen is the capital and most populous city of Denmark, with an urban population of 1.4 million. The city is situated mainly on the island of Zealand (Sjælland), with a smaller part on the island of Amager. Copenhagen is separated from Malmö, Sweden, by the Øresund strait. The Øresund Bridge connects the two cities by rail and road.', 'Copenhaga (português europeu) ou Copenhague (português brasileiro) é a capital e a maior cidade da Dinamarca. Está situada na costa oriental da ilha da Zelândia, com uma parte menor na ilha adjacente de Amager, ambas banhadas pelas águas do sul do estreito de Øresund, tendo do outro lado do referido estreito a cidade sueca de Malmö. É o principal centro de comércio, transportes, indústria e serviços da Dinamarca, albergando cerca de 25% da população total do país. É também a sede da comuna de Copenhaga, pertencente à Região da Capital.', 'Copenhagen', 'Copenhaga'),
  ('cordoba', 'Córdoba', 'Córdova', 'ES', 'Q5818', extensions.st_setsrid(extensions.st_makepoint(-4.78, 37.89), 4326)::extensions.geography, array[37.73,-4.94,38.05,-4.62]::double precision[], 'Europe/Madrid', true, 'Córdoba, or sometimes Cordova, is a city in Andalusia, Spain, and the capital of the province of Córdoba. With a population of 324,902 as of 2024, it is the 12th-largest city in Spain and the 3rd-largest in Andalusia.', 'Córdova é um município da província homónima, na comunidade autónoma da Andaluzia, na Espanha. O município tem 1 255,24 quilômetros quadrados de área e em 2021 tinha 322 071 habitantes.', 'Córdoba, Spain', 'Córdova (Espanha)'),
  ('dresden', 'Dresden', 'Dresden', 'DE', 'Q1731', extensions.st_setsrid(extensions.st_makepoint(13.738144, 51.049329), 4326)::extensions.geography, array[50.9749317,13.5793237,51.1776864,13.9660626]::double precision[], 'Europe/Berlin', true, 'Dresden is the capital city of the German state of Saxony and its second most populous city after Leipzig. It is the 12th most populous city of Germany, the fourth largest by area, and the third-most populous city in the area of former East Germany, after Berlin and Leipzig. Dresden''s urban area comprises the towns of Freital, Pirna, Radebeul, Meissen, Coswig, Radeberg, and Heidenau and has around 790,000 inhabitants. The Dresden metropolitan area has over 1.3 million inhabitants.', 'Dresden, ou em sua forma em português Dresda é uma cidade da Alemanha, capital do estado da Saxónia. Localiza-se nas margens do rio Elba. Tem 543 825 habitantes segundo censo de 2015. Dresden é uma cidade independente ou distrito urbano (Stadtkreis), ou seja, possui estatuto de distrito (Kreis).', 'Dresden', 'Dresden'),
  ('dublin', 'Dublin', 'Dublin', 'IE', 'Q1761', extensions.st_setsrid(extensions.st_makepoint(-6.260278, 53.349722), 4326)::extensions.geography, array[53.2987342,-6.3870259,53.4105416,-6.1148829]::double precision[], 'Europe/Dublin', true, 'Dublin is the capital and largest city of Ireland. Situated on Dublin Bay at the mouth of the River Liffey, it is in the province of Leinster, and is bordered on the south by the Dublin Mountains, part of the Wicklow Mountains range. Dublin is the largest city by population on the island of Ireland; at the 2022 census, the city council area had a population of 592,713, while the city, including suburbs, had a population of 1,263,219, and County Dublin had a population of 1,501,500. Various definitions of a metropolitan Greater Dublin Area exist.', 'Dublin ou, em língua portuguesa, Dublim é a capital e maior cidade da Irlanda. O nome em inglês deriva da palavra irlandesa "Dubhlinn", que significa "Lago Negro". Localiza-se na província de Leinster próxima ao ponto mediano da costa leste da Irlanda, sendo cortada pelo Rio Liffey e o centro da região de Dublin. Desde 1898 possui nível administrativo de condado (county-boroughs). Seus limites são os condados de Fingal a norte, Dublin meridional a sudoeste e Dun Laoghaire-Rathdown a sudeste. Tem uma população de 592 mil habitantes na cidade, e sua área metropolitana tem 1 263 219 habitantes.', 'Dublin', 'Dublin'),
  ('dubrovnik', 'Dubrovnik', 'Dubrovnik', 'HR', 'Q1722', extensions.st_setsrid(extensions.st_makepoint(18.108333, 42.640278), 4326)::extensions.geography, array[42.6208867,17.7655924,42.7803608,18.1581147]::double precision[], 'Europe/Zagreb', true, 'Dubrovnik, historically also known as Ragusa, is a city in southern Dalmatia, Croatia, by the Adriatic Sea. It is one of the most prominent tourist destinations in the Mediterranean, a seaport and the centre of the Dubrovnik-Neretva County. In 2021, its total population was 41,562. Recognizing its outstanding medieval architecture and fortifications, UNESCO inscribed the Old City of Dubrovnik as a World Heritage Site in 1979.', 'Dubrovnik é uma cidade costeira da Croácia localizada no extremo sul da Dalmácia, na ponta do istmo homônimo. É um dos destinos turísticos mais concorridos do Mar Adriático, um porto marítimo e a cidade mais importante do condado de Dubrovnik-Neretva. Em 2001 a população do município era de 43 770 habitantes, dos quais 30 436 na cidade, a maior parte deles de origem croata (88,39%), havendo ainda 3,26% de origem sérvia e 3,17% de bósnios.', 'Dubrovnik', 'Dubrovnik'),
  ('edinburgh', 'Edinburgh', 'Edimburgo', 'GB', 'Q23436', extensions.st_setsrid(extensions.st_makepoint(-3.189167, 55.953333), 4326)::extensions.geography, array[55.8187919,-3.4495326,56.0040837,-3.0749528]::double precision[], 'Europe/London', true, 'Edinburgh is the capital city of Scotland and one of its 32 council areas. It is located in southeast Scotland and is bounded to the north by the Firth of Forth and to the south by the Pentland Hills. Edinburgh had a population of
506,520 in 2020, making it the second-most-populous city in Scotland and the seventh-most-populous in the United Kingdom. The wider metropolitan area had a population of 912,490 in the same year.', 'Edimburgo é uma cidade no Reino Unido e capital da Escócia, situada na margem sul do estuário do rio Forth. É sede do parlamento escocês desde 1999. Segundo o census do ano 2011, a cidade conta com 495 360 habitantes, sendo a segunda cidade mais populosa da Escócia, depois de Glasgow, e a sétima cidade mais populosa do Reino Unido. Edimburgo é também a segunda cidade mais visitada de toda Grã-Bretanha, superada apenas por Londres.', 'Edinburgh', 'Edimburgo'),
  ('florence', 'Florence', 'Florença', 'IT', 'Q2044', extensions.st_setsrid(extensions.st_makepoint(11.254167, 43.771389), 4326)::extensions.geography, array[43.7258716,11.1497598,43.8354631,11.3389044]::double precision[], 'Europe/Rome', true, 'Florence is the capital and most populous city of the Italian region of Tuscany, and, as of 2026, with a population of 361,625, the 8th most populous city in the country. It is also the capital of the eponymous metropolitan province, which counts 988,494 inhabitants, while Eurostat estimates that 696,767 people live in the urban area of Florence. The Metropolitan Area of Florence, Prato and Pistoia, constituted in 2000 over an area of roughly 4,800 square kilometres (1,850 sq mi), is home to 1.5 million people.', 'Florença é um município italiano, sub-capital e maior cidade da Toscana e da província homônima, com cerca de 377 207 habitantes. Estende-se por uma área de 102,41 km², tendo uma densidade populacional de 3 683 hab/km². Faz fronteira com Bagno a Ripoli, Campi Bisenzio, Fiesole, Impruneta, Scandicci, Sesto Fiorentino. Florença foi durante muito tempo considerada a capital da moda.', 'Florence', 'Florença'),
  ('frankfurt', 'Frankfurt', 'Frankfurt', 'DE', 'Q1794', extensions.st_setsrid(extensions.st_makepoint(8.682222, 50.110556), 4326)::extensions.geography, array[50.0153529,8.4727605,50.2271424,8.8004049]::double precision[], 'Europe/Berlin', true, 'Frankfurt am Main, usually shortened to Frankfurt, is the most populous city in the German state of Hesse. Its 778,589 inhabitants as of 2025 make it the fifth-most populous city in Germany. Located in the foreland of the Taunus on its namesake river Main, the city forms a continuous conurbation with Offenbach; its urban area has a population of more than 2.7 million. Frankfurt is the heart of the larger Rhine-Main metropolitan region, which has a population of more than 5.8 million and is Germany''s second-largest metropolitan region after the Rhine-Ruhr region. Home to the European Central Bank, the city serves as one of the four institutional seats of the European Union. Frankfurt is classified by the GaWC as an Alpha world city.', 'Frankfurt am Main, Frankfurt sobre o Meno ou Francoforte do Meno, mais conhecida simplesmente como Frankfurt ou Francoforte, é a maior cidade do estado alemão de Hesse e a quinta maior cidade da Alemanha, com uma população de aproximadamente 732 688 habitantes em 2015. Sua área urbana tinha uma população estimada de 2,3 milhões de habitantes em 2010. A cidade está no centro da região metropolitana Frankfurt/Reno-Meno que tem uma população de 5,6 milhões de habitantes e é a segunda maior região metropolitana da Alemanha. Desde a expansão da União Europeia de 2007, o centro geográfico da União encontra-se a 40km a leste de Frankfurt.', 'Frankfurt', 'Frankfurt am Main'),
  ('gdansk', 'Gdańsk', 'Gdańsk', 'PL', 'Q1792', extensions.st_setsrid(extensions.st_makepoint(18.654023, 54.348291), 4326)::extensions.geography, array[54.2749189,18.4294955,54.4664485,18.9502437]::double precision[], 'Europe/Warsaw', true, 'Gdańsk is a city on the Baltic coast of northern Poland, and the capital of the Pomeranian Voivodeship. With a population of 486,492, it is Poland''s sixth-largest city and its major seaport. Gdańsk lies at the mouth of the Motława River and is situated at the southern edge of Gdańsk Bay, close to the city of Gdynia and the resort town of Sopot; these form a metropolitan area called the Tricity (Trójmiasto), with a population of approximately 1.5 million.', 'Gdansk é uma cidade com direitos de condado no norte da Polônia, na voivodia da Pomerânia, situada no mar Báltico, na foz do rio Motława no Vístula, na baía de Gdansk, a maior cidade do país em termos de área. Um centro cultural, científico e econômico e um entroncamento de tráfego do norte da Polônia, a capital da voivodia da Pomerânia. Um centro de economia marítima com o segundo maior porto comercial do mar Báltico.', 'Gdańsk', 'Gdansk'),
  ('geneva', 'Geneva', 'Genebra', 'CH', 'Q71', extensions.st_setsrid(extensions.st_makepoint(6.15, 46.2), 4326)::extensions.geography, array[46.1777742,6.1102325,46.2318859,6.1758454]::double precision[], 'Europe/Zurich', true, 'Geneva is the second-most populous city in Switzerland and the most populous in French-speaking Romandy. Situated in the southwest of the country, where the Rhône leaves Lake Geneva, it is the capital of the Republic and Canton of Geneva. Geneva is a global city, an international financial centre, and a worldwide centre for diplomacy, which has led to it being called the "Peace Capital".', 'Genebra — o pagus Genevensis — é uma cidade da Suíça, localizada no Cantão de Genebra, no oeste do país, figurando como a segunda mais populosa cidade suíça, depois de Zurique — e a mais populosa da região da Romandia, a parte francófona da Suíça. Situada onde o rio Ródano deixa o Lago Lemano, no chamado Pequeno Lago ou Lago de Genèbra, é a capital do Cantão de Genebra. O gentílico de Genebra é genebrino/a.', 'Geneva', 'Genebra'),
  ('genoa', 'Genoa', 'Génova', 'IT', 'Q1449', extensions.st_setsrid(extensions.st_makepoint(8.933889, 44.407222), 4326)::extensions.geography, array[44.3784709,8.6657444,44.5198419,9.0955805]::double precision[], 'Europe/Rome', true, 'Genoa is the sixth-largest city in Italy and the capital of the region of Liguria in northern Italy. As of 2026, 566,247 people live within the city''s administrative limits. While its metropolitan city has 820,691 inhabitants, more than 1.5 million people live in the wider metropolitan area stretching along the Italian Riviera.', 'GénovaPE ou GênovaPB é uma cidade e condados históricos da Itália, na região de Ligúria, cidade metropolitana de Génova, com cerca de 639 560 habitantes. Estende-se por uma área de 243 km², tendo uma densidade populacional de 2 484 hab/km². É limitada com Arenzano, Bargagli, Bogliasco, Bosio (AL), Campomorone, Ceranesi, Davagna, Masone, Mele, Mignanego, Montoggio, Sant''Olcese, Sassello (SV), Serra Riccò, Sori, Tiglieto, Urbe (SV).', 'Genoa', 'Génova'),
  ('ghent', 'Ghent', 'Gante', 'BE', 'Q1296', extensions.st_setsrid(extensions.st_makepoint(3.725278, 51.053611), 4326)::extensions.geography, array[50.9795422,3.5797616,51.188891,3.8493413]::double precision[], 'Europe/Brussels', true, 'Ghent is a city and a municipality in the East Flanders province of the Flemish Region of Belgium. It is the capital and largest city of the province and the third largest in the country, after Brussels and Antwerp. It is a port and university city.', 'Gante ou Gande é uma cidade e município belga, capital da província da Flandres Oriental.', 'Ghent', 'Gante'),
  ('glasgow', 'Glasgow', 'Glasgow', 'GB', 'Q4093', extensions.st_setsrid(extensions.st_makepoint(-4.25, 55.861111), 4326)::extensions.geography, array[55.7812791,-4.3932006,55.9296388,-4.0717169]::double precision[], 'Europe/London', true, 'Glasgow is the most populous city in Scotland, located on the banks of the River Clyde in west central Scotland. It is the third-most populous city in the United Kingdom and comprises 23 wards which represent the areas within the city boundaries. Glasgow is a leading city in Scotland for university education and research, finance, industry, commerce, shopping, culture and fashion, and was commonly referred to as the "second city of the British Empire" for much of the Victorian and Edwardian eras.', 'Glasgow é a maior cidade da Escócia, sendo a terceira mais populosa de todo o Reino Unido depois da capital Londres e de Birmingham. Com 580 690 habitantes, é a mais populosa das 32 autoridades unitárias da Escócia, conformando assim a mais populosa cidade britânica fora da Inglaterra. Situa-se às margens do rio Clyde, nas Lowlands centro-ocidentais. O nativo da cidade é chamado, em inglês, de Glaswegian, nome que também designa o fala peculiar local.', 'Glasgow', 'Glasgow'),
  ('gothenburg', 'Gothenburg', 'Gotemburgo', 'SE', 'Q25287', extensions.st_setsrid(extensions.st_makepoint(11.9675, 57.7075), 4326)::extensions.geography, array[57.5475,11.8075,57.8675,12.1275]::double precision[], 'Europe/Stockholm', true, 'Gothenburg is the second-largest city in Sweden, after the capital Stockholm, and the fifth-largest in the Nordic countries. Situated by the Kattegat on the west coast of Sweden 400 km from the capital, it is the gubernatorial seat of Västra Götaland County, with a population of approximately 600,000 in the city proper and about 1.1 million inhabitants in the metropolitan area.', 'Gotemburgo ou Goteburgo é a 2ª maior cidade da Suécia, depois da capital Estocolmo.
Está situada na pequena porção da província da Västergötland que atinge o mar, e localizada nas duas margens do rio Göta, imediatamente antes de este desaguar no estreito de Categate.', 'Gothenburg', 'Gotemburgo'),
  ('granada', 'Granada', 'Granada', 'ES', 'Q8810', extensions.st_setsrid(extensions.st_makepoint(-3.6, 37.175), 4326)::extensions.geography, array[37.1367032,-3.7003616,37.2250172,-3.4963241]::double precision[], 'Europe/Madrid', true, 'Granada is the capital city of the province of Granada, in the autonomous community of Andalusia, Spain. Granada is located at the foot of the Sierra Nevada mountains, at the confluence of four rivers, the Darro, the Genil, the Monachil and the Beiro. Ascribed to the Vega de Granada comarca, the city sits at an average elevation of 738 m (2,421 ft) above sea level 50 km from the Mediterranean coast, the Costa Tropical. With a population of 233,532 as of 2024, it is the 20th-largest city in Spain and is an important wine growing region. It was the last Muslim stronghold in Islamic Spain.', 'Granada é uma cidade e município espanhol, capital da homónima e da comarca da Veiga de Granada. Tem 88 km² de área e em 2021 tinha 231 775 habitantes. Em 2011, a área metropolitana de Granada tinha 523 845 habitantes.', 'Granada', 'Granada (Espanha)'),
  ('hamburg', 'Hamburg', 'Hamburgo', 'DE', 'Q1055', extensions.st_setsrid(extensions.st_makepoint(10.0, 53.55), 4326)::extensions.geography, array[53.39,9.84,53.71,10.16]::double precision[], 'Europe/Berlin', true, 'Hamburg, officially the Free and Hanseatic City of Hamburg, is the second-largest city in Germany after Berlin and sixth-largest city in the European Union, with a population of over 1.9 million. The Hamburg Metropolitan Region has a population of over 5.1 million and is the tenth-largest metropolitan region by GDP in the European Union. At the base of the Jutland Peninsula, the 110 km (68 mi)-long Elbe estuary begins in Hamburg, at the confluence of the Alster and Bille. Hamburg is one of Germany''s three city-states alongside Berlin and Bremen, and is surrounded by Schleswig-Holstein to the north and Lower Saxony to the south. The Port of Hamburg is Germany''s largest and Europe''s third-largest, after Rotterdam and Antwerp. The local dialect is a variant of Low Saxon.', 'Hamburgo, oficialmente Cidade Livre e Hanseática de Hamburgo é a segunda maior cidade da Alemanha, com uma população de aproximadamente 1,8 milhão de pessoas. A cidade possui uma região associada mais ampla.', 'Hamburg', 'Hamburgo'),
  ('heidelberg', 'Heidelberg', 'Heidelberg', 'DE', 'Q2966', extensions.st_setsrid(extensions.st_makepoint(8.694724, 49.409358), 4326)::extensions.geography, array[49.3520029,8.5731788,49.4596927,8.7939863]::double precision[], 'Europe/Berlin', true, 'Heidelberg is the fifth-largest city in the German state of Baden-Württemberg, and with a population of about 163,000, of which roughly a quarter consists of students, it is Germany''s 51st-largest city. Located about 78 km (48 mi) south of Frankfurt, Heidelberg is part of the densely populated Rhine-Neckar Metropolitan Region which has its centre in Mannheim.', 'Heidelberg, Heidelberga ou Edelberga é uma cidade da Alemanha, situada no vale do rio Neckar, no noroeste do Baden-Württemberg. É a quinta maior cidade deste Land, contando com 159 245 habitantes em 2021.', 'Heidelberg', 'Heidelberg'),
  ('helsinki', 'Helsinki', 'Helsínquia', 'FI', 'Q1757', extensions.st_setsrid(extensions.st_makepoint(24.9375, 60.170833), 4326)::extensions.geography, array[59.922486,24.7828026,60.2978497,25.2545116]::double precision[], 'Europe/Helsinki', true, 'Helsinki, until about 1930 known in English by its Swedish name of Helsingfors, is the capital and most populous city in Finland. It is on the shore of the Gulf of Finland and is the seat of southern Finland''s Uusimaa region. About 694,000 people live in the municipality, with 1.3 million in the capital region and 1.6 million in the metropolitan area. As the most populous urban area in Finland, it is the country''s most significant centre for politics, education, finance, culture, and research. Helsinki is 80 kilometres (50 mi) north of Tallinn, Estonia, 400 kilometres (250 mi) east of Stockholm, Sweden, and 300 kilometres (190 mi) west of Saint Petersburg, Russia. Helsinki is a bilingual municipality with Finnish and Swedish as its official languages.', 'Helsínquia (português europeu) ou Helsinque (português brasileiro), com mais de 620 mil habitantes, é a capital da República da Finlândia e a maior cidade do país.
É conhecida como a ”Filha do Mar Báltico” ou ”A cidade branca do Norte”.', 'Helsinki', 'Helsínquia'),
  ('innsbruck', 'Innsbruck', 'Innsbruck', 'AT', 'Q1735', extensions.st_setsrid(extensions.st_makepoint(11.393333, 47.268333), 4326)::extensions.geography, array[47.2107727,11.3016374,47.3601261,11.4559615]::double precision[], 'Europe/Vienna', true, 'Innsbruck is the capital of the Austrian state of Tyrol and the fifth-largest city in Austria. It is located on the River Inn, at its junction with the Wipp Valley, which provides access to the Brenner Pass 30 km (19 mi) to the south. The city had a population of 132,188 in 2024.', 'Innsbruck ou Insbruque é uma cidade no oeste da Áustria, capital do estado do Tirol. Ela é atravessada pelo rio Inn, de onde tem seu nome. A palavra bruck tem sua origem na palavra de língua alemã Brücke, que significa "ponte", o que leva a cidade a chamar-se "Ponte do Rio Inn". Localizada no vale do Inn, a cidade está no meio de altas montanhas, como o Nordkette ao norte, o Patscherkofel e o Nockspitze ao sul. Innsbruck é um renomado centro de esportes de inverno, sendo que sediou as olimpíadas de inverno nos anos de 1964 e 1976.', 'Innsbruck', 'Innsbruck'),
  ('istanbul', 'Istanbul', 'Istambul', 'TR', 'Q406', extensions.st_setsrid(extensions.st_makepoint(28.960278, 41.01), 4326)::extensions.geography, array[40.846381,28.8158715,41.166381,29.1358715]::double precision[], 'Europe/Istanbul', true, 'Istanbul is the largest city in Turkey, a megacity, constituting the country''s economic, cultural, and historical center. With a population of over 15 million, it is home to 18% of the population of Turkey. Istanbul is among the largest cities in Europe and in the world by population. It is a city on two continents; about two-thirds of its population live in Europe and the rest in Asia. Istanbul straddles the Bosphorus – one of the world''s busiest waterways – in northwestern Turkey, between the Sea of Marmara and the Black Sea. Its area of 5,461 square kilometers (2,109 mi2) is coterminous with Istanbul Province.', 'Istambul, a antiga Bizâncio e Constantinopla, é a maior cidade da Turquia e rivaliza com Londres como a mais populosa da Europa, com 15 067 724 habitantes na sua área metropolitana em 2018. A grande maioria da população é muçulmana, mas também há um grande número de laicos e uma minoria de cristãos e judeus.', 'Istanbul', 'Istambul'),
  ('krakow', 'Kraków', 'Cracóvia', 'PL', 'Q31487', extensions.st_setsrid(extensions.st_makepoint(19.937222, 50.061389), 4326)::extensions.geography, array[49.9676668,19.7922355,50.1261338,20.2173455]::double precision[], 'Europe/Warsaw', true, 'Kraków, officially the Royal Capital City of Kraków, is the second-largest and one of the oldest cities in Poland. Situated on the Vistula River in Lesser Poland Voivodeship, the city has a population of 816,614 (2025), with 1,428,363 people living in the Kraków metropolitan area. Kraków was the official capital of Poland until 1596 and has traditionally been one of the leading centres of Polish economic, academic, cultural, and artistic life. Its Old Town was declared a UNESCO World Heritage Site in 1978, one of the world''s first sites granted the status.', 'Cracóvia é uma cidade no sul da Polônia, na voivodia da Pequena Polônia. Estende-se por uma área de 326,85 km², com 774 839 habitantes, segundo os censo de 2019, com a densidade: 2 370,6 hab./km². Localiza-se no sul do país, nas margens do rio Vístula. É uma das cidades mais antigas da Polônia e a segunda maior cidade do país. A capital da Polônia em 1039-1079, 1138-1290 e 1296-1596, a principal cidade da coroação dos reis da Polônia e até 1609-1611 a cidade residencial dos reis da Polônia.', 'Kraków', 'Cracóvia'),
  ('kyiv', 'Kyiv', 'Kiev', 'UA', 'Q1899', extensions.st_setsrid(extensions.st_makepoint(30.523611, 50.45), 4326)::extensions.geography, array[50.2132422,30.2361453,50.5908142,30.8263593]::double precision[], 'Europe/Kyiv', true, 'Kyiv, also spelt Kiev, is the capital and most populous city of Ukraine. Located in the north-central part of the country, it straddles both banks of the Dnieper River. As of January 2022, the population of Kyiv was 2,952,301, making it the seventh-most populous city in Europe. Kyiv is an important industrial, scientific, educational, and cultural center. It is home to high-tech industries, higher education institutions, and historical landmarks. The city has an extensive public transport system, which includes the Kyiv Metro.', 'Kiev ou Kyiv, também conhecida como Quieve, ) é a capital e a cidade mais populosa da Ucrânia. Fica no centro-norte do país, ao longo do rio Dnieper. Em 1.º de janeiro de 2021, sua população era de 2 962 180 habitantes, tornando Kiev a sétima cidade mais populosa da Europa.', 'Kyiv', 'Kiev'),
  ('lisbon', 'Lisbon', 'Lisboa', 'PT', 'Q597', extensions.st_setsrid(extensions.st_makepoint(-9.139016, 38.708042), 4326)::extensions.geography, array[38.6913994,-9.2298356,38.7967584,-9.0863328]::double precision[], 'Europe/Lisbon', true, 'Lisbon is the capital and most populous city of Portugal, with an estimated population of 658,236 as of 2025, within its administrative limits and 3,353,000 within the metropolis, as of 2025. The city lies on the Atlantic Ocean in the western part of the Iberian Peninsula, fronting the northern shore of the River Tagus. The western portion of its metro area, the Portuguese Riviera, hosts the westernmost point of Continental Europe, culminating at Cabo da Roca.', 'Lisboa é a capital e maior cidade de Portugal, com uma população estimada de 548 703 habitantes em 2022 dentro dos seus limites administrativos numa área de cerca de 100 quilómetros quadrados. É a capital mais ocidental da Europa continental e a única ao longo da costa atlântica, estando as outras em ilhas. A cidade situa-se na parte ocidental da Península Ibérica, na margem norte do rio Tejo. Na parte ocidental da sua área metropolitana, a Costa do Estoril, situa-se o ponto mais ocidental da Europa continental, o cabo da Roca.', 'Lisbon', 'Lisboa'),
  ('liverpool', 'Liverpool', 'Liverpool', 'GB', 'Q24826', extensions.st_setsrid(extensions.st_makepoint(-2.991667, 53.407222), 4326)::extensions.geography, array[53.3115427,-3.0191726,53.4749885,-2.8180003]::double precision[], 'Europe/London', true, 'Liverpool is a port city and metropolitan borough in Merseyside, England. It is situated on the eastern side of the Mersey Estuary, near the Irish Sea, 178 miles (286 km) north-west of London. It had an estimated population of 508,961 in 2024. The city is within the larger Liverpool City Region, a combined authority area with a population of over 1.5 million.', 'Liverpool é uma cidade do condado de Merseyside, localizado no noroeste da Inglaterra, Reino Unido, no lado norte do estuário do Mersey. A cidade está localizada no extremo sudoeste do condado tradicional de Merseyside.', 'Liverpool', 'Liverpool'),
  ('ljubljana', 'Ljubljana', 'Liubliana', 'SI', 'Q437', extensions.st_setsrid(extensions.st_makepoint(14.506111, 46.051389), 4326)::extensions.geography, array[45.9740637,14.408617,46.1459968,14.755332]::double precision[], 'Europe/Ljubljana', true, 'Ljubljana is the capital and largest city of Slovenia, located along a trade route between the northern Adriatic Sea and the Danube region, north of the country''s largest marsh, it has been inhabited since prehistoric times. It is the country''s cultural, educational, economic, political and administrative centre and the seat of the Urban Municipality of Ljubljana.', 'Liubliana ou Ljubljana ) é a capital e maior cidade da Eslovênia, com cerca de 272 220 habitantes. Liubliana é a sede do município urbano de mesmo nome.', 'Ljubljana', 'Liubliana'),
  ('london', 'London', 'Londres', 'GB', 'Q84', extensions.st_setsrid(extensions.st_makepoint(-0.1275, 51.507222), 4326)::extensions.geography, array[51.2867601,-0.5103751,51.6918741,0.3340155]::double precision[], 'Europe/London', true, 'London is the capital and largest city of England and the United Kingdom, with a population of 9.14 million people in 2025. Its wider metropolitan area is the largest in Western Europe, with a population of 15.4 million. London stands on the River Thames in southeast England, at the head of a 50-mile (80 km) tidal estuary down to the North Sea, and has been a major settlement for nearly 2,000 years. Its ancient core and financial centre, the City of London, was founded by the Romans as Londinium and has retained its medieval boundaries. The City of Westminster, to the west of the City of London, has been the site of the national government and parliament for centuries. London grew rapidly in the 19th century, becoming the world''s largest city at the time. Since the 19th century the name "London" has referred to the metropolis around the City of London, historically split among the counties of Middlesex, Essex, Surrey, Kent and Hertfordshire. Since 1965 it has largely comprised the administrative area of Greater London, governed by 33 local authorities and the Greater London Authority.', 'Londres é a capital da Inglaterra e do Reino Unido. Por dois milénios, foi um grande povoado e sua história remonta à sua fundação pelos romanos, quando foi nomeada Londínio. O centro de Londres, antiga City of London, também conhecida como The Square Mile ou The City, mantém as suas fronteiras medievais. Pelo menos desde o século XIX, o nome "Londres" refere-se à metrópole desenvolvida em torno desse núcleo. Hoje, a maior parte dessa conurbação constitui a região da Grande Londres, cuja área administrativa tem seu próprio prefeito eleito e assembleia. A cidade abriga a sede da Comunidade das Nações.', 'London', 'Londres'),
  ('lucerne', 'Lucerne', 'Lucerna', 'CH', 'Q4191', extensions.st_setsrid(extensions.st_makepoint(8.3059, 47.0523), 4326)::extensions.geography, array[46.9980047,8.2065198,47.083522,8.4279853]::double precision[], 'Europe/Zurich', true, 'Lucerne or Luzern is a city and a municipality in central Switzerland, in the German-speaking portion of the country. Lucerne is the capital of the canton of Lucerne and part of the district of the same name. With a population of approximately 86,700 people, Lucerne is the most populous city in Central Switzerland, and a nexus of economics, transport, culture, and media in the region. The city''s urban area consists of 19 municipalities and towns with an overall population of about 247,400 people.', 'Lucerna é uma cidade da Suíça que dá nome ao cantão no qual está inserida; um dos 13 cantões que determinam a organização territorial de referência no país. Tem uma população de 82.257 habitantes (2019). Estende-se por uma área de 24,15 km², de densidade populacional de 3.406 hab/km². Confina com as seguintes comunas: Adligenswil, Ebikon, Emmen, Horw, Kriens e Meggen.', 'Lucerne', 'Lucerna'),
  ('luxembourg', 'Luxembourg', 'Luxemburgo', 'LU', 'Q1842', extensions.st_setsrid(extensions.st_makepoint(6.13, 49.611389), 4326)::extensions.geography, array[49.5609875,6.06917,49.6548682,6.2036491]::double precision[], 'Europe/Luxembourg', true, 'Luxembourg, also known as Luxembourg City, is the capital city of Luxembourg and the country''s most populous commune. Standing at the confluence of the Alzette and Pétrusse rivers in southern Luxembourg, the city lies in the center of Western Europe, situated 213 km (132 mi) by road from Brussels and 209 km (130 mi) from Cologne.', 'Luxemburgo é uma comuna do Luxemburgo com estatuto de cidade, pertencente ao distrito do Luxemburgo e ao cantão do Luxemburgo, e a capital do país. Luxemburgo é uma cidade muito desenvolvida em seu comércio e nas indústrias.', 'Luxembourg City', 'Luxemburgo (cidade)'),
  ('lviv', 'Lviv', 'Lviv', 'UA', 'Q36036', extensions.st_setsrid(extensions.st_makepoint(24.031592, 49.841952), 4326)::extensions.geography, array[49.7681748,23.8980549,49.9037122,24.1334136]::double precision[], 'Europe/Kyiv', true, 'Lviv is the fifth-largest city in Ukraine, as well as the largest city in the western part of the country, with a population of 723,403. It serves as the administrative center of Lviv Oblast and Lviv Raion, and is one of the main cultural centers of Ukraine. The city also hosts the administration of Lviv urban hromada. Lviv was named after Leo I of Galicia, the eldest son of Daniel, King of Ruthenia. During its history the city has had several names.', 'Levive, ou Lviv, também conhecida como Leópolis ou Lemberga, é uma cidade do oeste da Ucrânia. Localiza-se no oeste do país, perto da fronteira com a Polónia. Tem cerca de 800 mil habitantes. Foi fundada em 1256 pelo duque da Ruténia. Passou para soberania polaca em 1340, austríaca em 1772, de novo polaca em 1919 e ucraniana em 1939.', 'Lviv', 'Lviv'),
  ('lyon', 'Lyon', 'Lyon', 'FR', 'Q456', extensions.st_setsrid(extensions.st_makepoint(4.835, 45.7675), 4326)::extensions.geography, array[45.7073666,4.7718132,45.8082628,4.8984161]::double precision[], 'Europe/Paris', true, 'Lyon is a city in France. It is located at the confluence of the rivers Rhône and Saône, to the northwest of the French Alps, 391 km (243 mi) southeast of Paris, 278 km (173 mi) north of Marseille, and 113 km (70 mi) southwest of Geneva, Switzerland.', 'Lyon ou Lião é a terceira maior cidade da França. Está localizada na parte central do leste do país na confluência dos rios Ródano e Saône, a cerca de 470 km a sul de Paris, 320 km ao norte de Marselha e 55 km a leste de Saint-Étienne. Os habitantes da cidade são chamados de lioneses, em francês lyonnais.', 'Lyon', 'Lyon'),
  ('madrid', 'Madrid', 'Madrid', 'ES', 'Q2807', extensions.st_setsrid(extensions.st_makepoint(-3.703333, 40.416944), 4326)::extensions.geography, array[40.3119774,-3.8889539,40.6437293,-3.5183264]::double precision[], 'Europe/Madrid', true, 'Madrid is the capital and largest city of Spain. It had a population of over 3.4 million in the city proper in 2025, and a metropolitan area population of approximately 6.8 million. Madrid is the second-largest city in the European Union (EU), after Berlin, and its metropolitan area is the second-largest in the EU, after Paris. The municipality covers an area of 605.77 square kilometres (233.89 sq mi). Madrid lies on the River Manzanares in the central part of the Iberian Peninsula at about 660 metres (2,170 ft) above mean sea level. The capital city of both Spain and the surrounding autonomous community of Madrid, it is the political, economic and cultural centre of the country.', 'Madrid ou Madri (apenas em português brasileiro) é a capital e a maior cidade da Espanha. Em 2021 o município tinha 3 305 408 habitantes e a sua área metropolitana tinha cerca de 6,8 milhões de habitantes. É a segunda maior cidade da União Europeia (UE), depois de Berlim, e sua área metropolitana é a segunda maior da UE, depois de Paris. A área urbana da capital espanhola abrange um total de 604,3 de km2.', 'Madrid', 'Madrid'),
  ('malaga', 'Málaga', 'Málaga', 'ES', 'Q8851', extensions.st_setsrid(extensions.st_makepoint(-4.416667, 36.716667), 4326)::extensions.geography, array[36.6356619,-4.5878887,36.8940412,-4.2604897]::double precision[], 'Europe/Madrid', true, 'Málaga is a municipality of Spain and the capital of the province of Málaga, in the autonomous community of Andalusia. With a population of 592,346 in 2024, it is the 2nd-largest city in Andalusia and the 6th-largest in the country. It lies in Southern Iberia on the Costa del Sol of the Mediterranean, primarily on the left bank of the Guadalhorce. The urban core originally developed in the space between the Gibralfaro Hill and the Guadalmedina.', 'Málaga é uma cidade da Andaluzia, na Espanha. Capital da província homônima, localiza-se na costa sul do país, no Mediterrâneo. A cidade originou-se de uma colônia grega na antiguidade clássica. É a sexta maior cidade do país, com mais de 560 mil habitantes. Foi fundada pelos fenícios no século XII a.C. Foi incorporada à Coroa de Castela em 1487.', 'Málaga', 'Málaga'),
  ('manchester', 'Manchester', 'Manchester', 'GB', 'Q18125', extensions.st_setsrid(extensions.st_makepoint(-2.245278, 53.479444), 4326)::extensions.geography, array[53.3401044,-2.3199185,53.5445923,-2.1468288]::double precision[], 'Europe/London', true, 'Manchester is a city and metropolitan borough in North West England, at the centre of the eponymous county of Greater Manchester. It had a population of over 589,000 in 2024. It borders the Cheshire Plain to the south, the Pennines to the north and east, and the city of Salford to the west. The two cities and the surrounding towns form one of the United Kingdom''s most populous conurbations, the Greater Manchester Built-up Area, which has a population of 2.87 million.', 'Manchester é uma cidade do Reino Unido, no noroeste da Inglaterra. A aglomeração urbana de Manchester tem cerca de 3,6 milhões de habitantes, é a terceira cidade mais populosa da Inglaterra e junto com algumas outras cidades vizinhas, compõe o condado da Grande Manchester. A cidade é um centro industrial, econômico, e muitas companhias têm as sedes administrativas no centro da cidade ou num parque industrial ao este do centro, Trafford Park.', 'Manchester', 'Manchester'),
  ('marseille', 'Marseille', 'Marselha', 'FR', 'Q23482', extensions.st_setsrid(extensions.st_makepoint(5.376389, 43.296667), 4326)::extensions.geography, array[43.1696228,5.2287864,43.3910329,5.5324758]::double precision[], 'Europe/Paris', true, 'Marseille is a city in southern France, the prefecture of the Bouches-du-Rhône department and of the Provence-Alpes-Côte d''Azur region. Situated in Provence, it marks the eastern end of the Côte Bleue on the Mediterranean coast. Marseille is the second-most populous city proper in France, after Paris, with 886,040 inhabitants in 2023 over a municipal territory of 241 km2 (93 sq mi). Together with its suburbs and exurbs, the Marseille metropolitan area, which extends over 3,972 km2 (1,534 sq mi), had a population of 1,917,728 as of 2023. The cities of Marseille, Aix-en-Provence, and 90 suburban municipalities have formed since 2016 the Aix-Marseille-Provence Metropolis, an indirectly elected metropolitan authority now in charge of wider metropolitan issues, with a population of 1,939,077 as of 2023. The southeast of Marseille is in Calanques National Park, making Marseille the only large city in France to have a national park within city limits.', 'Marselha é a segunda mais populosa cidade de França e a mais antiga cidade francesa. Localizada na antiga província da Provença e na costa do Mediterrâneo, é o maior porto comercial do país.', 'Marseille', 'Marselha'),
  ('milan', 'Milan', 'Milão', 'IT', 'Q490', extensions.st_setsrid(extensions.st_makepoint(9.19, 45.466944), 4326)::extensions.geography, array[45.3867381,9.0408867,45.5358482,9.2781103]::double precision[], 'Europe/Rome', true, 'Milan is the capital and largest city of the region of Lombardy, in northern Italy, and the seat of the Metropolitan City of Milan. It is the second-largest city in Italy after the country’s capital, Rome, with a population of 1,362,863 in 2026. The city''s wider metropolitan area is the largest in Italy, and the fourth-largest in the European Union, with an estimated population of 6.55 million. Milan is considered Italy''s economic capital, and its metropolitan area accounts for about 20% of the country''s GDP.', 'Milão é uma comuna italiana, capital da região da Lombardia, província de Milão, com cerca de 1 404 239 habitantes. A área urbana de Milão é a quinta maior da União Europeia, com uma população estimada em 4 300 000 habitantes. A Região metropolitana de Milão é a maior e mais populosa da Itália, com uma população estimada em 7 400 000 habitantes de acordo com as estimativas da OCDE. Em termos europeus, a área metropolitana de Milão cobre uma área territorial equivalente à de Paris com uma população de mais de sete milhões de habitantes. Esta área encontra-se com os critérios das áreas estatísticas combinadas (CSAs) dos Estados Unidos. Pela população, Milão é a segunda maior cidade italiana e a terceira maior área metropolitana da União Europeia. Seus habitantes são referidos como "milanesi", ou, informalmente, como meneghini ou ambrosiani.', 'Milan', 'Milão'),
  ('minsk', 'Minsk', 'Minsk', 'BY', 'Q2280', extensions.st_setsrid(extensions.st_makepoint(27.561837, 53.902246), 4326)::extensions.geography, array[53.793847,27.3740176,53.9717897,28.0799469]::double precision[], 'Europe/Minsk', true, 'Minsk is the capital and largest city of Belarus, located on the Svislach and the now subterranean Nyamiha rivers. As the capital, Minsk has a special administrative status in Belarus and is the administrative centre of Minsk region and Minsk district. As of 2026, it has a population of about two million, making Minsk the 11th-most populous city in Europe. Minsk is one of the administrative capitals of the Commonwealth of Independent States (CIS) and the Eurasian Economic Union (EAEU).', 'Minsk ou, na sua forma aportuguesada, Minsque é uma cidade da Bielorrússia, capital e maior cidade do país e sede da Comunidade de Estados Independentes (CEI). Como capital, Minsk tem estatuto administrativo especial, além de ser também a capital do voblast (província) de Minsk. A cidade está situada junto aos rios Svislach e Niamiha, a 53°55′ N 27°33′ E. Sua população é de cerca de 2 milhões de habitantes (2018).', 'Minsk', 'Minsk'),
  ('monaco', 'Monaco', 'Mónaco', 'MC', 'Q235', extensions.st_setsrid(extensions.st_makepoint(7.42, 43.731111), 4326)::extensions.geography, array[43.7247,7.409,43.7519,7.4399]::double precision[], 'Europe/Monaco', true, 'Monaco, officially the Principality of Monaco, is a sovereign city-state and microstate in Western Europe. Situated on the French Riviera, it is a semi-enclave bordered by France to the north, east, and west, with the Mediterranean Sea to the south; the Italian region of Liguria is about 15 km (9.3 mi) east. With a population of 38,423 living in an area of 2.08 km2 (0.80 sq mi), Monaco is the second smallest sovereign state in the world, after Vatican City, as well as the most densely populated. It also has the world''s shortest national coastline of any non-landlocked nation, at 3.83 km (2.38 mi). Fewer than 10,000 of its residents are Monégasque nationals. Although French is the official language of Monaco, Italian and Monégasque are also widely spoken and understood.', 'Mónaco, oficialmente Principado do Mónaco (português europeu) ou Principado de Mônaco (português brasileiro), é uma cidade-estado soberana, e, portanto, um microestado, situado ao sul da França. Fazendo costa com o mar Mediterrâneo, o principado, fundado em 1297 pela Casa de Grimaldi — até hoje sua soberana —, fica a menos de 20 km a leste da cidade de Nice e 20 km a oeste da cidade de Ventimiglia. Possui aproximadamente uma área de 202 ha, sendo o segundo menor Estado do mundo, atrás apenas do Vaticano, com 44 hectares de área, e é o estado com a densidade populacional mais alta do mundo. Tem como forma de governo a monarquia constitucional, em que o monarca é Sua Alteza Sereníssima, o Príncipe Alberto II do Mónaco.', 'Monaco', 'Mónaco'),
  ('moscow', 'Moscow', 'Moscovo', 'RU', 'Q649', extensions.st_setsrid(extensions.st_makepoint(37.6175, 55.750556), 4326)::extensions.geography, array[55.57,37.36,55.92,37.86]::double precision[], 'Europe/Moscow', true, 'Moscow is the capital and largest city of Russia, situated on the Moskva River in Central Russia. The city has a population estimated at more than 13 million residents within city limits, more than 19.1 million residents in the urban area, and more than 21.5 million residents in the metropolitan area. The city covers an area of 2,511 square kilometers (970 sq mi); the urban area covers 5,891 square kilometers (2,275 sq mi); and the metropolitan area covers more than 26,000 square kilometers (10,000 sq mi). Moscow is among the world''s largest cities: the most populous city entirely in Europe, the largest urban and metropolitan areas in Europe, and the largest city by land area on the European continent.', 'Moscovo (português europeu) ou Moscou (português brasileiro) ) é a capital e maior cidade da Rússia. Fica às margens do rio Moscou na região central do país, com uma população estimada em 12,4 milhões de habitantes dentro dos limites da cidade, mais de 17 milhões de habitantes na área urbana e mais de 20 milhões de habitantes na área metropolitana. A cidade cobre uma área de 2 511 km², enquanto a área urbana cobre 5 891 km² e a área metropolitana cobre mais 26 mil km². Moscou está entre as maiores cidades do mundo, além de ser a maior área urbana e metropolitana da Europa e a maior cidade por área terrestre do continente europeu.', 'Moscow', 'Moscovo'),
  ('munich', 'Munich', 'Munique', 'DE', 'Q1726', extensions.st_setsrid(extensions.st_makepoint(11.575, 48.1375), 4326)::extensions.geography, array[48.0616244,11.360777,48.2481162,11.7229099]::double precision[], 'Europe/Berlin', true, 'Munich is the capital and most populous city of the German state of Bavaria. As of 30 November 2024, its population was 1,604,384, making it the third most-populous city in Germany after Berlin and Hamburg. Munich is the largest city in Germany that is not a state of its own, and it ranks as the 11th-largest city in the European Union (EU). The metropolitan area has around 3 million inhabitants, and the broader Munich Metropolitan Region is home to about 6.2 million people. It is the third largest metropolitan region by GDP in the EU. Munich is located on the river Isar north of the Alps. It is the seat of the Upper Bavarian administrative region. With 4,800 people per km2, Munich is Germany''s most densely populated municipality. It is also the second-largest city in the Bavarian dialect area after Vienna.', 'Munique é uma cidade da Alemanha, capital do estado alemão da Baviera, no sudeste do país. Conta atualmente cerca de 1,3 milhão de habitantes (2012), enquanto a sua região metropolitana, que engloba diversas cidades vizinhas ou próximas a Munique, abriga mais de 2,6 milhões de pessoas. É assim a cidade mais populosa da Baviera e do sul da Alemanha, e a terceira cidade mais populosa do país, depois da capital, Berlim, e de Hamburgo.', 'Munich', 'Munique'),
  ('naples', 'Naples', 'Nápoles', 'IT', 'Q2634', extensions.st_setsrid(extensions.st_makepoint(14.248611, 40.835833), 4326)::extensions.geography, array[40.791193,14.1320999,40.916123,14.3537681]::double precision[], 'Europe/Rome', true, 'Naples is the regional capital of Campania, southern Italy. With a population of 905,050 within the city''s administrative limits as of 2026, it is the largest city in southern Italy and the third-largest city in Italy after Rome and Milan, while its province-level municipality is the third most populous metropolitan city in Italy with a population of 2,954,847 residents – or the second largest according to OECD data. Its metropolitan area, the seventh most populous in the European Union, has a population of approximately 4.4 million and stretches beyond the boundaries of the city proper for approximately 30 kilometres. Naples also plays a key role in international diplomacy, being home to NATO''s Allied Joint Force Command Naples and the Parliamentary Assembly of the Mediterranean.', 'Nápoles é uma comuna do sul de Itália, capital da região da Campânia e da província de Nápoles, com cerca de 900 000 habitantes e com cerca de 4 400 000 habitantes na região metropolitana. Nápoles é a terceira cidade mais populosa da Itália após Roma e Milão e tem a segunda ou terceira maior região metropolitana do país. Estende-se por uma área de 117 km², com densidade populacional de densidade: 8 554,4 hab./km².', 'Naples', 'Nápoles'),
  ('nice', 'Nice', 'Nice', 'FR', 'Q33959', extensions.st_setsrid(extensions.st_makepoint(7.268333, 43.701944), 4326)::extensions.geography, array[43.6454189,7.1819535,43.7607635,7.323912]::double precision[], 'Europe/Paris', true, 'Nice is a city and commune, and the prefecture of the department of Alpes-Maritimes, and the administrative region of Provence-Alpes-Côte d''Azur, France. The Nice agglomeration extends beyond the administrative city limits, with a population of nearly one million over an area of approximately 744 km2 (287 sq mi) or about the size of Singapore. Located on the French Riviera, the southeastern coast of France on the Mediterranean Sea, at the foot of the French Alps, Nice is the second-largest French city on the Mediterranean coast and second-largest city in the Provence-Alpes-Côte d''Azur region after Marseille. It is approximately 13 kilometres (8 mi) from the principality of Monaco and 30 kilometres (19 mi) from the French–Italian border. Nice''s airport serves as a gateway to the region.', 'Nice é a quinta cidade mais populosa da França e a capital do departamento dos Alpes Marítimos. A área urbana de Nice se estende para além dos limites administrativos da cidade, com uma população de cerca de 1 milhão de habitantes, em uma área de 721 quilômetros quadrados. Localizada na região da Costa Azul, no litoral sul do país, nas margens do mar Mediterrâneo, Nice é a segunda maior cidade francesa na costa mediterrânica e a segunda maior cidade na região de Provença-Alpes-Costa Azul, depois de Marselha. Nice também está a cerca de 13 km de Mônaco e seu aeroporto é uma porta de entrada para o principado.', 'Nice', 'Nice'),
  ('nicosia', 'Nicosia', 'Nicósia', 'CY', 'Q3856', extensions.st_setsrid(extensions.st_makepoint(33.365, 35.1725), 4326)::extensions.geography, array[35.1521717,33.3358797,35.2017784,33.4182382]::double precision[], 'Asia/Nicosia', true, 'Nicosia, also known as Lefkosia or Lefkoşa, is the capital of Cyprus. It is the southeasternmost capital city among European Union member states. Its northern part is the de facto capital of Northern Cyprus.', 'Nicósia, é a capital e maior cidade de Chipre. À margem do rio Pedieos e quase no centro da ilha, Nicósia é a sede do governo bem como o principal centro de negócios. É a capital do distrito homónimo.', 'Nicosia', 'Nicósia'),
  ('nuremberg', 'Nuremberg', 'Nuremberga', 'DE', 'Q2090', extensions.st_setsrid(extensions.st_makepoint(11.0775, 49.453889), 4326)::extensions.geography, array[49.3314339,10.9887326,49.5407534,11.2825957]::double precision[], 'Europe/Berlin', true, 'Nuremberg is the second-largest city in the German state of Bavaria and the largest city in the cultural region of Franconia. Its 546,397 (2024) inhabitants make it the 13th-largest city in Germany. Situated on the Pegnitz, the city forms a continuous conurbation with the neighbouring cities of Fürth, Erlangen and Schwabach, with the built-up area comprising around 1.4 million inhabitants, while the larger Nuremberg Metropolitan Region has a population of approximately 3.6 million.', 'Nuremberga (português europeu) ou Nurembergue (português brasileiro) é uma cidade independente alemã, situada ao norte do estado da Baviera na região administrativa (Regierungsbezirk) da Média Francónia. Nuremberga é a maior cidade da região histórica Francônia com aproximadamente meio milhão de habitantes, tendo sua área metropolitana cerca de 1 milhão e 17 mil habitantes.', 'Nuremberg', 'Nuremberga'),
  ('oslo', 'Oslo', 'Oslo', 'NO', 'Q585', extensions.st_setsrid(extensions.st_makepoint(10.738889, 59.913333), 4326)::extensions.geography, array[59.8093113,10.4891652,60.1351064,10.9513894]::double precision[], 'Europe/Oslo', true, 'Oslo is the capital and most populous city of Norway. It constitutes both a county and a municipality. The municipality of Oslo had a population of 724,290 in 2025, while the city''s greater urban area had a population of 1,110,887 in 2025, and the metropolitan area had an estimated population of 1,546,706 in 2021.', 'Oslo ou mais raramente: [ˈusˈlu, ˈuʂlu]) é a capital da Noruega e a maior cidade do país. Anteriormente, entre 1624 e 1925, chamou-se Christiania, com a grafia alternativa Kristiania, adotada entre 1877 e 1897.', 'Oslo', 'Oslo'),
  ('oxford', 'Oxford', 'Oxford', 'GB', 'Q34217', extensions.st_setsrid(extensions.st_makepoint(-1.257778, 51.751944), 4326)::extensions.geography, array[51.7109788,-1.3042472,51.7962658,-1.1758134]::double precision[], 'Europe/London', true, 'Oxford is a cathedral city and non-metropolitan district in Oxfordshire, England, of which it is the county town.', 'Oxford, em português chamada Oxónia (português europeu) ou Oxônia (português brasileiro) ou Oxforde, é uma cidade e distrito de governo local do condado de Oxfordshire, Inglaterra, Reino Unido, com uma população de 134 248 habitantes. A Carfax Tower é normalmente considerada o centro da cidade. Está situada às margens do rio Tâmisa, que aí é chamado de rio Ísis.', 'Oxford', 'Oxford'),
  ('palermo', 'Palermo', 'Palermo', 'IT', 'Q2656', extensions.st_setsrid(extensions.st_makepoint(13.361262, 38.115658), 4326)::extensions.geography, array[38.0499137,13.242219,38.2245866,13.4520856]::double precision[], 'Europe/Rome', true, 'Palermo is the capital and largest city of the autonomous island region of Sicily in southern Italy, located on the eponymous gulf facing the Tyrrhenian Sea. A 2,700-year-old city, it is noted for its history, culture, architecture and gastronomy, playing an important role throughout much of its existence.', 'Palermo é uma comuna italiana, capital da cidade metropolitana de Palermo e da Região Siciliana, sendo a maior cidade da ilha da Sicília. Está localizada na costa norte da ilha, estendendo-se por uma área de 158 quilômetros quadrados.', 'Palermo', 'Palermo'),
  ('palma', 'Palma', 'Palma de Maiorca', 'ES', 'Q8826', extensions.st_setsrid(extensions.st_makepoint(2.649722, 39.566667), 4326)::extensions.geography, array[39.4066667,2.4897222,39.7266667,2.8097222]::double precision[], 'Europe/Madrid', true, 'Palma, also known as Palma de Mallorca, is the capital and largest city of the autonomous community of the Balearic Islands in Spain. It is situated on the south coast of Mallorca on the Bay of Palma. With a population of 438,234 as of 2024, it is the 8th-largest city in Spain.', 'Palma de Maiorca, oficialmente Palma e conhecida coloquialmente como Ciutat, é um município espanhol na comunidade autônoma das ilhas Baleares, da qual é a capital. localize-se na parte ocidental do mar Mediterrâneo, na costa sudoeste da ilha de Maiorca, a cerca de 250 km a leste da Península Ibérica.', 'Palma de Mallorca', 'Palma de Maiorca'),
  ('paris', 'Paris', 'Paris', 'FR', 'Q90', extensions.st_setsrid(extensions.st_makepoint(2.352222, 48.856667), 4326)::extensions.geography, array[48.8155755,2.224122,48.902156,2.4697602]::double precision[], 'Europe/Paris', true, 'Paris is the capital and largest city of France, with an estimated city population of 2.04 million in an area of 105.4 km2 (40.7 sq mi), as of January 2026, and a metropolitan population of 13.3 million (2023). Located on the Seine in the centre of the Île-de-France region, it is the largest metropolitan area and fourth-most populous city in the European Union (EU). Paris is nicknamed the "City of Light" mainly due to its leading role in the Age of Enlightenment.', 'Paris ) é a capital e a mais populosa cidade da França, com uma população estimada em 2025 de dois milhões de habitantes em uma área de 105 quilômetros quadrados. Desde o século XVII, Paris é um dos principais centros de finanças, diplomacia, comércio, moda, ciência e artes da Europa. A cidade de Paris é o centro e sede de governo da região administrativa de Ilha de França, que tem uma população estimada em 2025 de treze milhões de habitantes, ou cerca de 18% da população da França. Em 2017, a região de Paris teve um PIB de 709 bilhões de euros. De acordo com a Pesquisa de Custo de Vida da Economist Intelligence Unit em 2018, Paris era a segunda cidade mais cara do mundo, atrás apenas da Singapura e à frente de Zurique, Hong Kong, Oslo e Genebra.', 'Paris', 'Paris'),
  ('pisa', 'Pisa', 'Pisa', 'IT', 'Q13375', extensions.st_setsrid(extensions.st_makepoint(10.4, 43.716667), 4326)::extensions.geography, array[43.5807231,10.2684553,43.7507749,10.4562831]::double precision[], 'Europe/Rome', true, 'Pisa is a city and comune (municipality) in Tuscany, Central Italy, straddling the Arno just before it empties into the Ligurian Sea. It is the capital city of the Province of Pisa. Although Pisa is known worldwide for the Leaning Tower of Pisa, the city contains more than twenty other historic churches, and several medieval and Renaissance palaces, mostly facing each other on the avenues along the Arno ("Lungarno"). Much of the city''s architecture was financed from its history as one of the Italian maritime republics.', 'Pisa é uma comuna italiana da região da Toscana, província de Pisa, com cerca de 85 379 habitantes. Estende-se por uma área de 185 km², tendo uma densidade populacional de 462 hab/km². Faz fronteira com Cascina, Collesalvetti (LI), Livorno (LI), San Giuliano Terme. Descobertas arqueológicas recentes revelaram a existência de um grande porto fluvial da época romana no seu subsolo. Nessas descobertas foram encontradas mais de 30 embarcações de vários modelos, algumas delas intactas e ainda com a mercadoria que transportavam, tendo sido recuperados muitos objectos. Tal facto deve-se à conservação possibilitada pelos sedimentos depositados ao longo do tempo pelo Rio Arno. Há 20 séculos o estuário encontrava-se a 4 km do mar o que fazia do Porto das Maravilhas o maior porto romano, só igualado na sua importância pelo porto de Óstia, perto de Roma; actualmente a cidade encontra-se a 17 km do litoral. Acredita-se que a inclinação da famosa Torre de Pisa se deva ao facto de lá ter existido mar ou um estuário maior que o actual. O porto encontra-se sob a estação ferroviária de San Rossore. Diz a tradição que foi no Porto de Pisa que São Pedro desembarcou para pregar o Evangelho, tendo daí seguido para Roma.', 'Pisa', 'Pisa'),
  ('porto', 'Porto', 'Porto', 'PT', 'Q36433', extensions.st_setsrid(extensions.st_makepoint(-8.610833, 41.15), 4326)::extensions.geography, array[41.1383507,-8.691289,41.1859353,-8.5520792]::double precision[], 'Europe/Lisbon', true, 'Porto, also known in English as Oporto, is the second largest city in Portugal, after Lisbon. It is the capital of the Porto District and one of the Iberian Peninsula''s major urban areas. Porto city proper, which is the entire municipality of Porto, is small compared to its metropolitan area, with an estimated population of 273,476 people in a municipal area of 41.42 km2 (16 sq mi). As of 2025, the Porto metropolitan area has around 1.9 million people in an area of 2,395 km2 (925 sq mi), making it the second-largest urban area in Portugal. It is recognized as a global city with a Gamma + rating from the Globalization and World Cities Research Network.', 'Porto é uma cidade portuguesa e capital da sub-região da Área Metropolitana do Porto e da região Norte, pertencendo ao distrito do Porto. É sede do Município do Porto que tem uma área total de 41,42 km2, 248 769 habitantes em 2023 e uma densidade populacional de 6 006 hab./km2, subdividido em 7 freguesias. O município é limitado a norte pelos municípios de Matosinhos e Maia, a leste por Gondomar, a sul por Vila Nova de Gaia e a oeste pelo Oceano Atlântico.', 'Porto', 'Porto'),
  ('prague', 'Prague', 'Praga', 'CZ', 'Q1085', extensions.st_setsrid(extensions.st_makepoint(14.421389, 50.0875), 4326)::extensions.geography, array[49.9419006,14.2244355,50.1774302,14.7067867]::double precision[], 'Europe/Prague', true, 'Prague is the capital and largest city of the Czech Republic and the historical capital of Bohemia. Located on the Vltava River, the city has a population of about 1.4 million, making it the twelfth-largest city in the European Union. Its metropolitan area is home to approximately 2.3 million people.', 'Praga ) é a capital e a maior cidade da Chéquia, situada na margem do Vltava. Conhecida como "cidade das cem cúpulas", Praga é um dos mais belos e antigos centros urbanos da Europa, famosa pelo extenso patrimônio arquitetônico e rica vida cultural. Importante também como núcleo de transportes e comunicações, é o principal centro econômico e industrial da Chéquia. Situada na Boêmia central, a cidade de Praga localiza-se sobre colinas, em ambas as margens do rio Vltava, pouco antes de sua confluência com o rio Elba. O curso sinuoso do rio através da cidade, cheia de belas e antigas pontes, contrasta com a presença imponente do grande Castelo de Praga em Hradcany, que domina a capital na margem esquerda (oriental) do Vltava.', 'Prague', 'Praga'),
  ('reykjavik', 'Reykjavík', 'Reykjavík', 'IS', 'Q1764', extensions.st_setsrid(extensions.st_makepoint(-21.935, 64.1475), 4326)::extensions.geography, array[64.0404021,-21.9838299,64.3153711,-21.4019991]::double precision[], 'Atlantic/Reykjavik', true, 'Reykjavík is the capital and largest city of Iceland. It is located on the southern shore of the Faxaflói bay in southwest Iceland and has a latitude of 64°08′ N, making it the world''s northernmost capital of a sovereign state. Reykjavík has a population of around 140,000 as of 2026, and the surrounding Capital Region has a population of around 252,000, constituting approximately 64% of Iceland''s population.', 'Reiquiavique ou Reykjavík é a capital da Islândia e, pela sua posição, é também a capital mais setentrional do mundo. Com uma população de 135 700 habitantes e de 243 000 na Região da Capital (2024), é o coração da atividade cultural, econômica e governamental da Islândia, e um destino turístico popular.', 'Reykjavík', 'Reiquiavique'),
  ('riga', 'Riga', 'Riga', 'LV', 'Q1773', extensions.st_setsrid(extensions.st_makepoint(24.106944, 56.9475), 4326)::extensions.geography, array[56.8573462,23.9325504,57.0861068,24.3245042]::double precision[], 'Europe/Riga', true, 'Riga, officially Riga State City, is the capital, primate, and largest city of Latvia and the second most-populous city in the Baltics. Home to 588,911 inhabitants, the city accounts for a third of Latvia''s total population. The population of Riga metropolitan area, which stretches beyond the city limits, is estimated at 847,162. The city lies on the Gulf of Riga at the mouth of the Daugava river where it meets the Baltic Sea. Riga''s territory covers 307.17 km2 (118.60 sq mi) and lies 1–10 m (3–33 ft) above sea level on a flat and sandy plain.', 'Riga ) é a capital e a maior cidade da Letônia. Está localizada no nordeste da Europa, sendo banhada pelo mar Báltico e situado-se no coração do golfo de Riga, na foz do rio Duína Ocidental. É a mais importante cidade da Letônia, principal centro político, cultural, populacional e econômico do país. Segundo dados de 2013, possuí uma população de 643 615 habitantes, ou aproximadamente um terço da população letã no mesmo período. É a mais populosa das capitais bálticas, e a segunda maior área metropolitana da região, depois da região metropolitana de Vilnius.', 'Riga', 'Riga'),
  ('rome', 'Rome', 'Roma', 'IT', 'Q220', extensions.st_setsrid(extensions.st_makepoint(12.482778, 41.893056), 4326)::extensions.geography, array[41.6556417,12.2344416,42.1410285,12.8557603]::double precision[], 'Europe/Rome', true, 'Rome is the capital and largest city of Italy. It is also the administrative centre of the Lazio region and of the Metropolitan City of Rome. A special municipality named Roma Capitale with a population of 2.7 million in an area of 1,287.36 km2 (497.1 mi2), Rome is the third most populous city in the European Union by population within city limits. The Metropolitan City of Rome Capital, with a population of 4.2 million, is the most populous metropolitan city in Italy. Its metropolitan area is the third-most populous within Italy. Rome is located in the central-western portion of the Italian Peninsula, within Lazio (Latium), along the shores of the Tiber Valley. Vatican City—the smallest country in the world and headquarters of the worldwide Catholic Church under the governance of the Holy See—is an independent country within Rome''s municipal boundaries, the only existing example of a country within a city. Rome is often referred to as the "City of Seven Hills" due to its geography, and also as the "Eternal City". Rome is generally considered to be one of the cradles of Western civilization and Western Christian culture, and the centre of the Catholic Church.', 'Roma é a capital da Itália e da região do Lácio, além de ser o centro da Cidade Metropolitana de Roma e de uma comuna especial. Com 2 860 009 residentes em 1 285 km², Roma é a comuna mais populosa do país e a terceira cidade mais populosa da União Europeia. A Cidade Metropolitana de Roma, com uma população de 4 355 725 habitantes, é a cidade metropolitana mais populosa da Itália e sua área metropolitana é a terceira mais populosa do país. A cidade está localizada na porção centro-oeste da Península Itálica, ao longo das margens do rio Tibre. Cidade do Vaticano é um país independente dentro dos limites de Roma, o único exemplo existente de um país dentro de uma cidade no mundo. Roma é muitas vezes referida como a "Cidade das Sete Colinas" devido à sua localização geográfica, e também como a "Cidade Eterna", por conta de sua longa história, e porque ele inicia como uma cidade, mas depois ela se torna em um império. Roma é geralmente considerada o "berço da cultura e da civilização ocidental e cristã" e o centro da Igreja Católica.', 'Rome', 'Roma'),
  ('rotterdam', 'Rotterdam', 'Roterdão', 'NL', 'Q34370', extensions.st_setsrid(extensions.st_makepoint(4.48, 51.92), 4326)::extensions.geography, array[51.8616672,4.3793095,51.9942735,4.6018092]::double precision[], 'Europe/Amsterdam', true, 'Rotterdam is the second-largest city in the Netherlands by population and the largest by area (319.4 km2). It is in the province of South Holland, part of the North Sea mouth of the Rhine–Meuse–Scheldt delta, via the New Meuse inland shipping channel, dug to connect to the Meuse at first and now to the Rhine.', 'Roterdão (português europeu) ou Roterdã (português brasileiro) é a segunda maior e mais importante cidade dos Países Baixos, ficando atrás somente da capital, Amsterdã. Sede do maior porto marítimo da Europa, possui cerca de 617 347 habitantes. Está situada às margens do rio Nieuwe Maas na província da Holanda do Sul. Parte da cidade está na ilha IJsselmonde.', 'Rotterdam', 'Roterdão'),
  ('saint-petersburg', 'Saint Petersburg', 'São Petersburgo', 'RU', 'Q656', extensions.st_setsrid(extensions.st_makepoint(30.316667, 59.95), 4326)::extensions.geography, array[59.6337832,29.4257576,60.2448369,30.7594934]::double precision[], 'Europe/Moscow', true, 'Saint Petersburg, formerly known as Petrograd (Петроград), and later Leningrad (Ленинград), is the second-largest city in Russia, after Moscow, the nation''s capital. Situated on the Neva River at the head of the Gulf of Finland on the Baltic Sea, its area of 1,439 square kilometers (556 sq mi) makes it the smallest administrative division of Russia by area. The city had a population of 5,601,911 residents as of 2021, with more than 6.4 million people living in the metropolitan area. Saint Petersburg is the fourth-most populous city in Europe, the most populous city on the Baltic Sea, and the world''s northernmost city of more than 1 million residents. As the former capital of the Russian Empire, and a historically strategic Baltic port, it is governed as a federal city.', 'São Petersburgo ou Sampetersburgo é a segunda maior cidade da Rússia, politicamente incorporada como uma cidade autônoma. Ela está localizada ao longo do rio Neva, na entrada do Golfo da Finlândia, no Mar Báltico. Em 1914, o nome da cidade foi mudado para Petrogrado e, em 1924, para Leningrado. Em 1991, após o colapso da União Soviética, a cidade voltou ao seu nome original. É frequentemente chamada apenas de Petersburgo e informalmente conhecida como Peter.', 'Saint Petersburg', 'São Petersburgo'),
  ('salzburg', 'Salzburg', 'Salzburgo', 'AT', 'Q34713', extensions.st_setsrid(extensions.st_makepoint(13.045, 47.8), 4326)::extensions.geography, array[47.7512115,12.9856478,47.8543925,13.1275256]::double precision[], 'Europe/Vienna', true, 'Salzburg is the fourth-largest city in Austria. In 2026 its population was 157,994. The city lies on the Salzach River, near the border with Germany and at the foot of the Alps mountains.', 'Salzburgo ou Salisburgo é uma cidade da Áustria localizada às margens do Rio Salzach, no centro-oeste do país, próximo à fronteira com o estado alemão da Baviera. É a capital do estado homônimo e conta com 146 631 habitantes (2014), sendo a quarta maior cidade da Áustria, após Viena, Graz e Linz. Salzburgo é uma cidade estatutária (Statutarstadt), ou seja, possui estatuto de distrito e se estende por cerca de 66 km². O centro histórico de Salzburgo é Patrimônio Mundial da UNESCO desde 1996.', 'Salzburg', 'Salzburgo'),
  ('san-sebastian', 'San Sebastián', 'San Sebastián', 'ES', 'Q10313', extensions.st_setsrid(extensions.st_makepoint(-1.98, 43.32), 4326)::extensions.geography, array[43.2178373,-2.0868082,43.3381594,-1.8878839]::double precision[], 'Europe/Madrid', true, 'San Sebastián or Donostia, officially known by the bilingual name Donostia / San Sebastián, is a city and municipality located in the Basque Autonomous Community in Spain. It lies on the coast of the Bay of Biscay, 20 km from the Spain–France border. The capital city of the province of Gipuzkoa, it has a population of 188,487 as of 2024, with its metropolitan area being 436,500 in 2010. Locals call themselves donostiarra (singular) in Basque, also using this term when speaking in Spanish. It is also a part of Basque Eurocity Bayonne-San Sebastián.', 'São Sebastião, oficialmente Donostia/San Sebastián, é uma cidade espanhola localizada no País Basco espanhol, capital da província de Guipúscoa. Rodeada pela Baía da Concha, à beira do golfo da Biscaia, a cidade tem cerca de 183 000 habitantes, enquanto sua periferia possui aproximadamente 400 mil residentes.', 'San Sebastián', 'São Sebastião (País Basco)'),
  ('santiago-de-compostela', 'Santiago de Compostela', 'Santiago de Compostela', 'ES', 'Q14314', extensions.st_setsrid(extensions.st_makepoint(-8.533333, 42.883333), 4326)::extensions.geography, array[42.8236718,-8.6320116,42.989631,-8.3900878]::double precision[], 'Europe/Madrid', true, 'Santiago de Compostela, alternatively abbreviated to Santiago or Compostela, is the capital of the autonomous community of Galicia, Spain. It is located in the province of A Coruña, in the northwest of the Iberian Peninsula. The city has its origin in the shrine of Saint James the Great, now the Cathedral of Santiago de Compostela, as the destination of the Way of St. James, a leading Catholic pilgrimage route since the 9th century. In 1985, the city''s Old Town was designated a UNESCO World Heritage Site.', 'Santiago de Compostela é uma cidade e município no noroeste de Espanha. É capital da comunidade autónoma da Galiza e faz parte da província da Corunha e da comarca de Santiago. O município tem 220 km² de área e em 2021 tinha 97 858 habitantes.', 'Santiago de Compostela', 'Santiago de Compostela'),
  ('sarajevo', 'Sarajevo', 'Sarajevo', 'BA', 'Q11194', extensions.st_setsrid(extensions.st_makepoint(18.413056, 43.856389), 4326)::extensions.geography, array[43.8209096,18.2494674,43.966773,18.5171652]::double precision[], 'Europe/Sarajevo', true, 'Sarajevo is the capital and largest city of Bosnia and Herzegovina, with a population of 275,524 in its administrative limits. The Sarajevo Canton, containing the city of Sarajevo and nearby municipalities, is home to 413,593 inhabitants. Located within the greater Sarajevo valley of Bosnia, it is surrounded by the Dinaric Alps and situated along the Miljacka River in the heart of the Balkans, a region of Southeastern Europe.', 'Saraievo, Sarajevo ou, na sua forma antiga, hoje em desuso, Serajevo, é a capital e a maior cidade da Bósnia e Herzegovina. O censo de 2013 indicou uma população de 405 930 habitantes, o que indica um pequeno crescimento nas mais de duas décadas desde o censo de 1991, que apontava uma população de 329 672 habitantes.', 'Sarajevo', 'Sarajevo'),
  ('seville', 'Seville', 'Sevilha', 'ES', 'Q8717', extensions.st_setsrid(extensions.st_makepoint(-5.995, 37.388611), 4326)::extensions.geography, array[37.3002036,-6.0329183,37.4529579,-5.8191571]::double precision[], 'Europe/Madrid', true, 'Seville is the capital and largest city of the Spanish autonomous community of Andalusia and the province of Seville. It is situated on the lower reaches of the River Guadalquivir, in the southwest of the Iberian Peninsula.', 'Sevilha é uma cidade espanhola situada a sudoeste da Península Ibérica, na comunidade autónoma da Andaluzia. É capital da província homónima. Segundo censo de 2019, havia 1 228 479 de habitantes. Sevilha tem a terceira maior catedral no mundo. Uma das pessoas lá enterradas é Cristóvão Colombo.', 'Seville', 'Sevilha'),
  ('siena', 'Siena', 'Siena', 'IT', 'Q2751', extensions.st_setsrid(extensions.st_makepoint(11.331389, 43.318333), 4326)::extensions.geography, array[43.2498952,11.2300025,43.3663312,11.4285563]::double precision[], 'Europe/Rome', true, 'Siena is a city in the region of Tuscany in central Italy, and the capital of the province of Siena. With a population of 53,180, it is the 12th-largest city in the region.', 'Siena é uma cidade e sede de comuna italiana na província de mesmo nome, na região da Toscana, com cerca de 52 775 habitantes. Estende-se por uma área de 118 km², tendo uma densidade populacional de 447 hab/km². Faz fronteira com Asciano, Castelnuovo Berardenga, Monteriggioni, Monteroni d''Arbia e Sovicille.', 'Siena', 'Siena'),
  ('sofia', 'Sofia', 'Sófia', 'BG', 'Q472', extensions.st_setsrid(extensions.st_makepoint(23.321726, 42.697886), 4326)::extensions.geography, array[42.5579851,23.167997,42.864302,23.6215817]::double precision[], 'Europe/Sofia', true, 'Sofia is the capital and largest city of Bulgaria. It is situated in the Sofia Valley at the foot of the Vitosha mountain, in the western part of the country. The city is built west of the Iskar river and has many mineral springs, such as the Sofia Central Mineral Baths. It has a humid continental climate.', 'Sófia ) é a capital e maior cidade da Bulgária. Localiza-se no oeste do país, aos pés do Maciço Vitosha, e constitui o principal centro administrativo, cultural, econômico e educacional búlgaro. A cidade possui população de 1 401 553 habitantes (2009), enquanto sua região metropolitana abriga cerca de 1 449 277 habitantes, sendo uma das maiores áreas urbanas da União Europeia. Além de capital nacional, Sófia também constitui uma província (óblast) da Bulgária.', 'Sofia', 'Sófia'),
  ('split', 'Split', 'Split', 'HR', 'Q1663', extensions.st_setsrid(extensions.st_makepoint(16.44, 43.51), 4326)::extensions.geography, array[43.4985847,16.3877955,43.5322835,16.5303557]::double precision[], 'Europe/Zagreb', true, 'Split is the second-largest city in Croatia, after the capital Zagreb, situated on the eastern shore of the Adriatic Sea. As the administrative seat of Split-Dalmatia County and the largest city on the Croatian coast, it serves as a key economic, cultural, and transportation hub for the region. Developed around the historic core of Diocletian''s Palace and extending across a central peninsula toward its surrounding suburbs and hinterland, Split combines a continuous urban tradition spanning more than seventeen centuries with a contemporary role as one of Croatia''s leading tourist destinations. The city itself has a population of over 160,000, while the metropolitan area encompasses approximately 310,000 inhabitants.', 'Split é a maior e mais importante cidade da Dalmácia, bem como o centro administrativo do condado de Split-Dalmácia, na Croácia. Está situada numa pequena península na margem oriental do Mar Adriático, na base dos montes Kozjak e Mosor. Com uma população de 193.867 habitantes (2005), 95,15% dos quais de origem étnica croata, é a segunda maior cidade da Croácia.', 'Split, Croatia', 'Split'),
  ('stockholm', 'Stockholm', 'Estocolmo', 'SE', 'Q1754', extensions.st_setsrid(extensions.st_makepoint(18.068611, 59.329444), 4326)::extensions.geography, array[59.2272524,17.7606914,59.4402839,18.2000781]::double precision[], 'Europe/Stockholm', true, 'Stockholm is the capital and most populous city of Sweden, as well as the largest urban area in the Nordic countries. Approximately 1 million people live in the municipality, with 1.6 million in the urban area, and 2.5 million in the metropolitan area. The city stretches across fourteen islands where Lake Mälaren flows into the Baltic Sea. Outside the city to the east, and along the coast, is the island chain of the Stockholm archipelago. The area has been settled since the Stone Age, in the 6th millennium BC, and was founded as a city in 1252 by Swedish statesman Birger Jarl. The city serves as the county seat of Stockholm County.', 'Estocolmo é a capital e a maior cidade da Suécia.
Sua localização, centrada em 19 ilhas e ilhotas, juntamente com a área continental circundante, tem sido historicamente importante.', 'Stockholm', 'Estocolmo'),
  ('strasbourg', 'Strasbourg', 'Estrasburgo', 'FR', 'Q6602', extensions.st_setsrid(extensions.st_makepoint(7.752222, 48.573333), 4326)::extensions.geography, array[48.4919357,7.6881371,48.6461896,7.8360646]::double precision[], 'Europe/Paris', true, 'Strasbourg is a prefecture and commune, and the largest city of the Grand Est region of northeastern France, in the historic region of Alsace. It is the prefecture of the Bas-Rhin department and the official seat of the European Parliament.', 'Estrasburgo é uma comuna situada no leste da França, na margem esquerda do Rio Reno. É a capital da região administrativa de Grande Leste e do departamento do Baixo Reno.', 'Strasbourg', 'Estrasburgo'),
  ('tallinn', 'Tallinn', 'Tallinn', 'EE', 'Q1770', extensions.st_setsrid(extensions.st_makepoint(24.745, 59.437222), 4326)::extensions.geography, array[59.3518076,24.55017,59.5915769,24.9262831]::double precision[], 'Europe/Tallinn', true, 'Tallinn is the capital and largest city of Estonia. Located on a bay in northern Estonia, on the shore of the Gulf of Finland of the Baltic Sea, it has a population of 452,563 as of 2026, making it the third most-populous city in the Baltics. As of 2024, the population of the Tallinn metropolitan area is estimated at 646,315. Tallinn is the main governmental, financial, industrial, and cultural centre of Estonia. It is located 187 kilometres (116 mi) northwest of the country''s second largest city, Tartu, however, only 80 kilometres (50 mi) south of Helsinki, the capital city of Finland. It is also 320 kilometres (200 mi) west of Saint Petersburg, Russia, 300 kilometres (190 mi) north of Riga, Latvia, and 380 kilometres (240 mi) east of Stockholm, Sweden. From the 13th century until the first half of the 20th century, Tallinn was known in most of the world by variants of its other historical name, Reval.', 'Tallinn, Talim, Taline ou Talin é a capital, centro financeiro e maior cidade da Estónia, localizada no golfo da Finlândia, na costa norte do país junto ao mar Báltico, a 80 quilómetros a sul de Helsínquia. Tem cerca de 400 000 habitantes, aproximadamente um terço da população total do país.', 'Tallinn', 'Tallinn'),
  ('thessaloniki', 'Thessaloniki', 'Salonica', 'GR', 'Q17151', extensions.st_setsrid(extensions.st_makepoint(22.935556, 40.640278), 4326)::extensions.geography, array[40.5856783,22.8994639,40.6531231,22.989905]::double precision[], 'Europe/Athens', true, 'Thessaloniki is the capital and largest city of the administrative region of Central Macedonia, and the second-largest city in Greece. It is the largest city of Northern Greece, with over 300,000 in the city proper and slightly over one million inhabitants in its metropolitan area, the capital of the geographic region of Macedonia, and the Decentralized Administration of Macedonia and Thrace. It is also known in Greek as i Symprotévousa, literally "the co-capital", a reference to its historical status as the "co-reigning" city of the Byzantine Empire alongside Constantinople.', 'Salonica, também conhecida como Tessalónica (português europeu) ou Tessalônica (português brasileiro) é a segunda maior cidade da Grécia e a principal cidade da região grega da Macedônia. Em 2011, a população da região metropolitana era de 1 104 460, dos quais 788 952 na cidade propriamente dita e 325 182 no município.', 'Thessaloniki', 'Salonica'),
  ('toledo', 'Toledo', 'Toledo', 'ES', 'Q5836', extensions.st_setsrid(extensions.st_makepoint(-4.033333, 39.866667), 4326)::extensions.geography, array[39.8108202,-4.1800787,39.9254339,-3.8147929]::double precision[], 'Europe/Madrid', true, 'Toledo is a city and municipality in Spain. It is the capital of the province of Toledo and the de jure seat of the government and parliament of the autonomous community of Castilla–La Mancha.', 'Toledo é um município da Espanha na província de Toledo, comunidade autónoma de Castela-Mancha. Tem 232,1 quilómetros quadrados de área e em 2021 tinha 85 449 habitantes.', 'Toledo, Spain', 'Toledo'),
  ('toulouse', 'Toulouse', 'Toulouse', 'FR', 'Q7880', extensions.st_setsrid(extensions.st_makepoint(1.443333, 43.604444), 4326)::extensions.geography, array[43.5326969,1.3503311,43.6687119,1.5153356]::double precision[], 'Europe/Paris', true, 'Toulouse is a city in Southern France, the prefecture of the Haute-Garonne department and of the Occitania region. The city is on the banks of the River Garonne, 150 kilometres from the Mediterranean Sea, 230 km (143 mi) from the Atlantic Ocean and 680 km (420 mi) from Paris. It is the fourth-largest city in France after Paris, Marseille, and Lyon, with 514,819 inhabitants within its municipal boundaries (2023); its metropolitan area has a population of 1,529,112 inhabitants (2023). Toulouse is the central city of one of the 22 metropolitan councils of France. Between the 2014 and 2020 censuses, its metropolitan area was the third fastest growing among metropolitan areas larger than 500,000 inhabitants in France.', 'Toulouse ou Tolosa é a capital do departamento francês da Alta Garona e da região de Occitânia. A cidade fica nas margens do rio Garona, a 150 km do mar Mediterrâneo, a 230 km do Atlântico e a 680 km de Paris. É a quarta maior cidade da França, com 504 078 habitantes em 2021. A área metropolitana de Toulouse, com 1 490 640 habitantes em 2021, é a quarta maior região metropolitana do país, depois de Paris, Lyon e Marselha, e à frente de Lille e Bordéus.', 'Toulouse', 'Toulouse'),
  ('turin', 'Turin', 'Turim', 'IT', 'Q495', extensions.st_setsrid(extensions.st_makepoint(7.676111, 45.079167), 4326)::extensions.geography, array[45.0067924,7.5778348,45.1402175,7.7733388]::double precision[], 'Europe/Rome', true, 'Turin is a city and a business and cultural centre in northern Italy. It is the capital and largest city of Piedmont and of the Metropolitan City of Turin. From 1861 to 1865, it was the first capital of the Kingdom of Italy. The city is mainly on the western bank of the River Po, below its Susa Valley, and is surrounded by the western Alpine arch and Superga hill. The population of the city proper is 855,654 as of 2026, while the population of the urban area is estimated by Eurostat to be 1.7 million inhabitants. The Turin metropolitan area is estimated by the OECD to have a population of 2.2 million.', 'Turim é uma comuna italiana, capital e maior cidade da região do Piemonte, e efetivamente a quarta maior cidade do país, com uma população de 910 188 habitantes (2009), estando atrás apenas de Roma, Milão e Nápoles. Estende-se por uma área de 130 km², tendo uma densidade populacional de 6 596 hab/km². Faz fronteira com Venaria Reale, Settimo Torinese, Borgaro Torinese, San Mauro Torinese, Collegno, Rivoli, Baldissero Torinese, Grugliasco, Pino Torinese, Orbassano, Pecetto Torinese, Beinasco, Moncalieri e Nichelino.', 'Turin', 'Turim'),
  ('utrecht', 'Utrecht', 'Utreque', 'NL', 'Q803', extensions.st_setsrid(extensions.st_makepoint(5.121667, 52.090833), 4326)::extensions.geography, array[52.026282,4.970096,52.1420506,5.195155]::double precision[], 'Europe/Amsterdam', true, 'Utrecht is the fourth-largest city of the Netherlands, as well as the capital and the most populous city of the province of Utrecht. The municipality of Utrecht is located in the eastern part of the Randstad conurbation, in the very centre of mainland Netherlands, and includes Haarzuilens, Vleuten and De Meern. It has a population of 378,140 as of January 2026.', 'Utreque é a capital e a cidade mais populosa da província homónima, nos Países Baixos. Com mais de 335 000 habitantes é a quarta mais populosa cidade do país, atrás de Amesterdão, Haia e Roterdão. Situa-se no centro do país, próximo de um ramal do rio Reno. Por causa da sua locação central no país, a cidade é um nó importante de tráfego, tanto o rodoviário como o ferroviário.', 'Utrecht', 'Utreque'),
  ('valencia', 'Valencia', 'Valência', 'ES', 'Q8818', extensions.st_setsrid(extensions.st_makepoint(-0.376389, 39.47), 4326)::extensions.geography, array[39.2784496,-0.4325512,39.566609,-0.2725205]::double precision[], 'Europe/Madrid', true, 'Valencia, known officially in Valencian as València, is the capital and largest city of the Valencian Community and the province of the same name in Spain. It is located on the banks of the Turia, on the east coast of the Iberian Peninsula on the Mediterranean Sea. With a population of 824,340, it is the third most-populous city in Spain. The urban area of Valencia has 1.6 million people while the metropolitan region has 2.5 million.', 'Valência é um município da Espanha, capital da província homónima e da Comunidade Valenciana. É a cidade mais populosa da sua comunidade autónoma e a terceira mais populosa da Espanha. O município tem 134,65 km² de área e em 2021 tinha 789 744 habitantes. Em 2014, a área metropolitana tinha 1 542 233 habitantes.', 'Valencia', 'Valência'),
  ('valletta', 'Valletta', 'Valeta', 'MT', 'Q23800', extensions.st_setsrid(extensions.st_makepoint(14.5125, 35.897778), 4326)::extensions.geography, array[35.8577778,14.4725,35.9377778,14.5525]::double precision[], 'Europe/Malta', true, 'Valletta, also known as Città Umilissima, is the capital city of Malta and one of its 68 council areas. Located between the Grand Harbour to the east and Marsamxett Harbour to the west, its population as of 2021 was 5,157. As Malta''s capital city, it is a commercial centre for shopping, bars, dining, and café life. It is also the southernmost capital of Europe, and, at just 0.61 square kilometres (0.24 sq mi), it is the European Union''s second-smallest capital city.', 'Valeta é a capital da República de Malta. Tem uma população de cerca de 6 315 habitantes e situa-se na costa leste da ilha de Malta. Situa-se na península homónima, dispondo de dois portos naturais: Marsamxett e Grand Harbour.
O nome oficial da cidade foi dado pela Ordem de São João e é Humilissima Civitas Valletta — A Humílima Cidade de Valeta. Contudo, com a construção dos bastiões, muralhas e revelins, ao mesmo tempo que a cidade se desenvolvia com numerosos edifícios barrocos, a cidade passou a ser apelidada de Superbissima. Em maltês é comummente conhecida com Il-Belt - A Cidade.', 'Valletta', 'Valeta'),
  ('venice', 'Venice', 'Veneza', 'IT', 'Q641', extensions.st_setsrid(extensions.st_makepoint(12.331944, 45.439722), 4326)::extensions.geography, array[45.2312466,12.1668349,45.5779981,12.5965709]::double precision[], 'Europe/Rome', true, 'Venice is a coastal city in northeastern Italy and the capital of the region of Veneto, as well as the Metropolitan City of Venice. It is built on a group of 126 islands that are separated by expanses of open water and by canals; portions of the city are linked by 472 bridges.', 'Veneza é uma cidade no nordeste da Itália situada sobre um grupo de 117 pequenas ilhas separadas por canais e ligadas por pontes. Ela está localizada na pantanosa Lagoa de Veneza, que se estende ao longo da costa entre as bocas dos rios Po e Piave. Veneza é famosa pela beleza de sua arquitetura e obras de arte. Uma parte da cidade está listada como um Patrimônio Mundial, juntamente com a sua lagoa.', 'Venice', 'Veneza'),
  ('verona', 'Verona', 'Verona', 'IT', 'Q2028', extensions.st_setsrid(extensions.st_makepoint(10.992778, 45.438611), 4326)::extensions.geography, array[45.3494402,10.8768512,45.5418375,11.1239]::double precision[], 'Europe/Rome', true, 'Verona is the largest city in the region of Veneto in Italy, with a population of 255,139 as of 2026. It is one of the seven provincial capitals of the region, and is also the 2nd-largest city in northeast Italy. The metropolitan area of Verona covers an area of 1,426 km2 (550.58 sq mi) and has a population of 714,310 inhabitants. It is one of the main tourist destinations in Northern Italy because of its artistic heritage and several annual fairs and shows as well as the opera season in the Arena, an ancient Roman amphitheater.', 'Verona ) é uma cidade italiana da região do Vêneto, com 255 748 habitantes. Estende-se por uma área de 206,63 km², tendo uma densidade populacional de 1 182 hab/km². É banhada pelo rio Adige, está a cerca de 30 quilômetros do Lago de Garda e fica aos pés das montanhas de Lessínia.', 'Verona', 'Verona'),
  ('vienna', 'Vienna', 'Viena', 'AT', 'Q1741', extensions.st_setsrid(extensions.st_makepoint(16.3725, 48.208333), 4326)::extensions.geography, array[48.1179069,16.181831,48.3226679,16.5775132]::double precision[], 'Europe/Vienna', true, 'Vienna is the capital, most populous city, and one of the nine states of Austria. It is Austria''s primate city, with just over two million inhabitants. Its larger metropolitan area has a population of nearly 2.9 million, representing nearly one-third of the country''s population. Vienna is the cultural, economic, and political centre of the country, the fifth-largest city by population in the European Union, and the most populous of the cities on the river Danube.', 'Viena ) é a capital da Áustria e um dos nove estados austríacos. Com mais de dois milhões de habitantes, em 2025, é a cidade mais populosa da Áustria contando, ainda, com 2,9 milhões de habitantes em sua região metropolitana — o que equivale a cerca de um quarto da população total do país. Viena é, ainda, a sétima maior cidade da União Europeia e a segunda maior cidade de língua alemã no mundo, depois de Berlim. A cidade é basicamente uma das muitas comunidades da Áustria, mas também é uma cidade legal na classificação de um distrito político e, desde 29 de dezembro de 1921, a "lei da separação" constitucional classifica-a como um estado, sua posição original mantida até hoje.', 'Vienna', 'Viena'),
  ('vilnius', 'Vilnius', 'Vilnius', 'LT', 'Q216', extensions.st_setsrid(extensions.st_makepoint(25.28, 54.687222), 4326)::extensions.geography, array[54.5689058,25.0245351,54.83232,25.4814574]::double precision[], 'Europe/Vilnius', true, 'Vilnius is the capital and largest city of Lithuania and the most-populous city in the Baltic states. The city''s estimated July 2026 population was 619,405, and the Vilnius urban area has an estimated population of 767,907.', 'Vilnius ), Vílnius ou Vilna é a capital da República da Lituânia. É a cidade mais populosa do país, com cerca de 600 mil habitantes.', 'Vilnius', 'Vilnius'),
  ('warsaw', 'Warsaw', 'Varsóvia', 'PL', 'Q270', extensions.st_setsrid(extensions.st_makepoint(21.011111, 52.23), 4326)::extensions.geography, array[52.0978497,20.8516882,52.3681531,21.2711512]::double precision[], 'Europe/Warsaw', true, 'Warsaw, officially the Capital City of Warsaw, is the capital and most populous city of Poland. The metropolis stands on the river Vistula in east-central Poland. Its population is officially estimated at 1.87 million residents within a greater metropolitan area of around 3.5 million residents, which makes Warsaw the 7th most populous city in the European Union. The city area measures 517 square kilometres and comprises 18 districts, while the metropolitan area covers 6,100 square kilometres. Warsaw is classified as an alpha global city, a major political, economic and cultural hub, and the country''s seat of government. It is also the capital of the Masovian Voivodeship.', 'Varsóvia é a capital e maior cidade da Polónia. Localiza-se nas margens do rio Vístula, a cerca de 260 km da costa do mar Báltico e 300 km das montanhas dos Cárpatos. A sua população, em 2012, era estimada em 1 716 855 habitantes. A cidade, que também é a capital do Voivodato de Masóvia, é sede de numerosas indústrias, instituições de ensino superior, uma orquestra filarmónica, o maior Teatro Nacional do mundo e a Ópera.', 'Warsaw', 'Varsóvia'),
  ('wroclaw', 'Wrocław', 'Breslávia', 'PL', 'Q1799', extensions.st_setsrid(extensions.st_makepoint(17.0325, 51.11), 4326)::extensions.geography, array[51.0426686,16.8073393,51.2100604,17.1762192]::double precision[], 'Europe/Warsaw', true, 'Wrocław is a city in southwestern Poland, and the capital of the Lower Silesian Voivodeship. It is the largest city and historical capital of the regions of Silesia and Lower Silesia. It lies on the banks of the Oder (Odra) River in the Silesian Lowlands. In 2025, the official population of Wrocław was 672,545, making it the third-largest city in Poland. The population of the Wrocław metropolitan area is around 1.25 million.', 'Breslávia é uma cidade da Baixa Silésia, na Polônia. Tem cerca de 672 000 habitantes, o que a torna a terceira mais populosa cidade da Polônia. Localiza–se nas margens do rio Oder, a cerca de 350 km ao sudoeste de Varsóvia.', 'Wrocław', 'Breslávia'),
  ('york', 'York', 'Iorque', 'GB', 'Q42462', extensions.st_setsrid(extensions.st_makepoint(-1.083333, 53.95), 4326)::extensions.geography, array[53.8745672,-1.223712,54.0568664,-0.9196707]::double precision[], 'Europe/London', true, 'York is a cathedral city in North Yorkshire, England, with Roman origins, sited at the confluence of the rivers Ouse and Foss. It has many historic buildings and other structures, including the minster, castle and city walls, all of which are Grade I listed. It is the traditional county town of Yorkshire, and the administrative centre of the City of York district. It is located 27 miles (43 km) north-east of Leeds, 90 miles (140 km) south of Newcastle upon Tyne and 207 miles (333 km) north of London. York''s built-up area had a recorded population of 141,685 at the 2021 census.', 'Iorque ) é uma cidade histórica murada na confluência dos rios Ouse e Foss em North Yorkshire, Inglaterra. É uma tradicional cidade do condado de Yorkshire, a qual dá o seu nome. Tem uma rica herança e tem servido de cenário para grandes eventos políticos na Inglaterra durante a maior parte de seus dois milênios de existência. Oferece uma grande variedade de atrações históricas, das quais a Catedral de Iorque é a mais proeminente, e uma variedade de atividades desportivas e culturais tornando-se um destino turístico popular para milhões de pessoas.', 'York', 'Iorque'),
  ('zagreb', 'Zagreb', 'Zagreb', 'HR', 'Q1435', extensions.st_setsrid(extensions.st_makepoint(15.977222, 45.813056), 4326)::extensions.geography, array[45.6139895,15.7732052,45.9691466,16.2395548]::double precision[], 'Europe/Zagreb', true, 'Zagreb is the capital and largest city of Croatia. It is in the north of the country, along the Sava River, at the southern slopes of the Medvednica mountain. Zagreb stands near the international border between Croatia and Slovenia at an elevation of approximately 158 m (518 ft) above sea level. At the 2021 census, the city itself had a population of 767,131, while the population of the Zagreb metropolitan area is 1,086,528.', 'Zagreb ou, na forma aportuguesada, Zagrebe, é a capital e a maior cidade da Croácia. Situa-se no norte do país, junto ao rio Sava e nas encostas meridionais da montanha Medvednica. No censo de 2021, a unidade administrativa Cidade de Zagreb tinha 767 131 habitantes. O assentamento de Zagreb propriamente dito tinha 663 592 habitantes. A Aglomeração Urbana de Zagreb, delimitada oficialmente para fins de planejamento e composta pela capital e por outras 29 cidades e municípios, tinha 1 051 045 habitantes em 2021.', 'Zagreb', 'Zagreb'),
  ('zurich', 'Zurich', 'Zurique', 'CH', 'Q72', extensions.st_setsrid(extensions.st_makepoint(8.541111, 47.374444), 4326)::extensions.geography, array[47.3202184,8.4480182,47.434665,8.6254529]::double precision[], 'Europe/Zurich', true, 'Zurich is the largest city in Switzerland and the capital of the canton of Zurich. It is in north-central Switzerland, at the northwestern tip of Lake Zurich. As of the end of 2025, the municipality had a population of 440,935, while the urban area was home to 1.45 million people (2020), and the Zurich metropolitan area had a total population of 2.1 million (2020). Zurich is a hub for railways, roads, and air traffic. Both Zurich Airport and Zurich''s main railway station are the largest and busiest in the country.', 'Zurique é a maior cidade da Suíça. Localiza-se no nordeste do país, no centro da zona germanófona, possui 379 915 habitantes (2012), sendo mais populosa do que qualquer outra cidade suíça. Sua região metropolitana, também a maior aglomeração urbana do país, conta com cerca de 1,8 milhão de habitantes em 2011, abrigando dessa forma, cerca de 20% da população do país. É a capital do Cantão de Zurique.', 'Zurich', 'Zurique')
